@Injectable()
export class EventhubService implements OnModuleInit {
  private readonly logger = new AppLogger(EventhubService.name);

  public constructor(private readonly configService: ConfigService) {}

  public get pubSubName(): string {
    return this.configService.get<string>('eventhub.pubSubName') ?? '';
  }

  public get topicPlantHYR(): string {
    return this.configService.get<string>('eventhub.topicPlantHYR') ?? '';
  }

  public get topicEwmPlants(): string {
    return this.configService.get<string>('eventhub.topicEwmPlants') ?? '';
  }

  public get topicEwmWorcenters(): string {
    return this.configService.get<string>('eventhub.topicEwmWorcenters') ?? '';
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    // Check if all required configuration values are present
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'pubSubName', value: this.pubSubName },
      { key: 'topicPlantHYR', value: this.topicPlantHYR },
      { key: 'topicEwmWorcenters', value: this.topicEwmWorcenters },
      { key: 'topicEwmPlants', value: this.topicEwmPlants },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.logger.debug('All required configurations are properly set');
  }
}

