import { Controller, Delete, HttpException, HttpStatus } from '@nestjs/common';
import {
  ApiInternalServerErrorResponse,
  ApiOperation,
  ApiResponse,
  ApiTags,
} from '@nestjs/swagger';
import { IngestionEventTrackingService } from './ingestion-event-tracking.service';
import { AppLogger } from '@/common/logger/app-logger';

@ApiTags('Data Ingestion')
@Controller('data-ingestion')
export class IngestionEventTrackingController {
  private readonly logger = new AppLogger(
    IngestionEventTrackingController.name,
  );

  public constructor(
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
  ) {}

  @Delete('deleteExpiredIngestionEventTracking')
  @ApiOperation({
    description:
      'Deletes Ingestion Event Tracking  that are older than the defined retention time (1 day after launchDatetime).',
    summary: 'Delete expired Ingestion Event Tracking records',
  })
  @ApiResponse({
    description:
      'Successfully deleted expired Ingestion Event Tracking records',
    schema: {
      example: {
        deletedCount: 5,
      },
    },
    status: HttpStatus.OK,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  public async deleteExpiredIngestionEventTracking(): Promise<string> {
    try {
      const result =
        await this.ingestionEventTrackingService.deleteExpiredIngestionEventTracking();
      this.logger.log(
        `Expired ingestion event tracking deleted successfully ${result.deletedCount}`,
      );
      return `Expired ingestion event tracking deleted successfully ${result.deletedCount}`;
    } catch (error) {
      this.logger.error(
        `Failed to delete expired ingestion event tracking records: ${error.message}`,
        error.stack,
      );
      throw new HttpException(
        `Failed to delete expired ingestion event tracking records: ${error.message}`,
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }
}

