import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { PropertyDataType } from '@/modules/isa95-common/property-data-type/property-data-type.entity';
import { CreatePropertyDataTypeDto } from '@/modules/isa95-equipment-model/dtos/create-property-data-type.dto';
import { UpdatePropertyDataTypeDto } from '@/modules/isa95-equipment-model/dtos/update-property-data-type.dto';

@Injectable()
export class PropertyDataTypeCrudService {
  private readonly logger = new AppLogger(PropertyDataTypeCrudService.name);

  public constructor(
    @InjectRepository(PropertyDataType)
    private readonly propertyDataTypeRepository: Repository<PropertyDataType>,
  ) {}

  public async create(
    payload: CreatePropertyDataTypeDto,
  ): Promise<PropertyDataType | undefined> {
    const existingType = await this.propertyDataTypeRepository.findOne({
      where: { code: payload.code },
    });

    if (existingType) {
      this.logger.warn(
        `Property data type with code ${payload.code} already exists`,
      );
      return undefined;
    }

    const propertyDataType = this.propertyDataTypeRepository.create(payload);
    return this.propertyDataTypeRepository.save(propertyDataType);
  }

  public async findAll(): Promise<Array<PropertyDataType>> {
    return this.propertyDataTypeRepository.find({
      order: { id: 'ASC' },
    });
  }

  public async findOne(id: number): Promise<PropertyDataType | undefined> {
    const propertyDataType = await this.propertyDataTypeRepository.findOne({
      where: { id },
    });

    if (!propertyDataType) {
      this.logger.warn(`Property data type with id ${id} not found`);
      return undefined;
    }

    return propertyDataType;
  }

  public async update(
    id: number,
    payload: UpdatePropertyDataTypeDto,
  ): Promise<PropertyDataType | undefined> {
    const propertyDataType = await this.findOne(id);

    if (!propertyDataType) {
      return undefined;
    }

    if (payload.code !== undefined) {
      propertyDataType.code = payload.code;
    }

    return this.propertyDataTypeRepository.save(propertyDataType);
  }

  public async remove(id: number): Promise<void> {
    const response = await this.propertyDataTypeRepository.delete({ id });

    if (!response.affected) {
      this.logger.warn(`Property data type with id ${id} not found`);
    }
  }
}

