/**
 * DTO helper that converts equipment class property semantics between
 * API-facing camelCase and database-facing snake_case shapes.
 */
export class EquipmentClassPropertySemanticsTransformerDto {
  public static toApi(
    value?: Record<string, unknown>,
  ): Record<string, unknown> | undefined {
    if (value === undefined) {
      return undefined;
    }

    const semantics = { ...value };

    if (
      semantics.class_property_type !== undefined &&
      semantics.classPropertyType === undefined
    ) {
      semantics.classPropertyType = semantics.class_property_type;
    }

    if (
      semantics.default_value !== undefined &&
      semantics.defaultValue === undefined
    ) {
      semantics.defaultValue = semantics.default_value;
    }

    if (
      semantics.allowed_values !== undefined &&
      semantics.allowedValues === undefined
    ) {
      semantics.allowedValues = Array.isArray(semantics.allowed_values)
        ? semantics.allowed_values
        : undefined;
    }

    if (semantics.ui_element_type !== undefined) {
      semantics.uiElementType = semantics.ui_element_type ?? undefined;
    }

    if (semantics.extract_api_path !== undefined) {
      semantics.extractApiPath = semantics.extract_api_path ?? undefined;
    }

    delete semantics.class_property_type;
    delete semantics.default_value;
    delete semantics.allowed_values;
    delete semantics.ui_element_type;
    delete semantics.extract_api_path;

    return semantics;
  }

  public static toDatabase(
    value?: Record<string, unknown>,
  ): Record<string, unknown> | undefined {
    if (value === undefined) {
      return undefined;
    }

    const semantics = { ...value };

    if (
      semantics.classPropertyType !== undefined &&
      semantics.class_property_type === undefined
    ) {
      semantics.class_property_type = semantics.classPropertyType;
      delete semantics.classPropertyType;
    }

    if (
      semantics.defaultValue !== undefined &&
      semantics.default_value === undefined
    ) {
      semantics.default_value = semantics.defaultValue;
      delete semantics.defaultValue;
    }

    if (
      semantics.allowedValues !== undefined &&
      semantics.allowed_values === undefined
    ) {
      semantics.allowed_values = Array.isArray(semantics.allowedValues)
        ? semantics.allowedValues
        : undefined;
      delete semantics.allowedValues;
    }

    if (
      semantics.uiElementType !== undefined &&
      semantics.ui_element_type === undefined
    ) {
      semantics.ui_element_type = semantics.uiElementType ?? undefined;
      delete semantics.uiElementType;
    }

    if (
      semantics.extractApiPath !== undefined &&
      semantics.extract_api_path === undefined
    ) {
      semantics.extract_api_path = semantics.extractApiPath ?? undefined;
      delete semantics.extractApiPath;
    }

    return semantics;
  }
}

