import { EquipmentClassRelatedEquipmentPropertyDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-related-equipment-property.dto';
import { EquipmentClassRelatedEquipmentDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-related-equipment.dto';
import {
  PaginatedResponseDto,
  PaginationDto,
} from '@/modules/isa95-equipment-model/dtos/pagination.dto';
import { UpdateEquipmentClassDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-class.dto';
import { EquipmentDescriptionByLanguage } from '@/modules/isa95-equipment-model/equipment/equipment-description-by-language/equipment-description-by-language.entity';
import { EquipmentPropertyDescription } from '@/modules/isa95-equipment-model/equipment/equipment-property-description/equipment-property-description.entity';
import { Equipment } from '@/modules/isa95-equipment-model/equipment/equipment.entity';
import { EquipmentClassDescription } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-description/equipment-class-description.entity';
import { EquipmentClassInheritance } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-inheritance/equipment-class-inheritance.entity';
import { EquipmentClassProperty } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-property/equipment-class-property.entity';
import { EquipmentClass } from '@/modules/isa95-equipment-model/equipment-class/equipment-class.entity';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';
import { EquipmentProperty } from '@/modules/isa95-equipment-model/shared/equipment-property/equipment-property.entity';
import { buildCustomCode } from '@/modules/isa95-equipment-model/utils/custom-code.util';

@Injectable()
export class EquipmentClassCrudService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static selectEquipmentDescription(
    descriptions: Array<EquipmentDescriptionByLanguage> | undefined,
    language: string,
  ): EquipmentDescriptionByLanguage | undefined {
    if (!descriptions || descriptions.length === 0) {
      return undefined;
    }

    return (
      descriptions.find(
        (description) => description.code?.trim() === language,
      ) ??
      descriptions.find(
        (description) =>
          description.code?.trim() ===
          EquipmentClassCrudService.defaultDescriptionLanguageCode,
      ) ??
      descriptions[0]
    );
  }

  private static mapEquipmentForClass(
    equipment: Equipment,
    equipmentClassId: number,
    language: string,
  ): EquipmentClassRelatedEquipmentDto {
    const selectedDescription =
      EquipmentClassCrudService.selectEquipmentDescription(
        equipment.descriptions,
        language,
      );

    const properties = (equipment.equipmentProperties ?? [])
      .filter((property) => property.equipmentClassId === equipmentClassId)
      .sort((left, right) => left.id - right.id)
      .map<EquipmentClassRelatedEquipmentPropertyDto>((property) => ({
        id: property.id,
        equipmentClassId: property.equipmentClassId,
        propertiesJson: property.propertiesJson ?? {},
      }));

    return {
      code: equipment.code?.trim() ?? '',
      description: selectedDescription?.description ?? null,
      descriptionLanguageCode: selectedDescription?.code?.trim() ?? null,
      equipmentLevelCode: equipment.equipmentLevel?.code ?? null,
      equipmentLevelId: equipment.equipmentLevelId,
      id: equipment.id,
      parentEquipmentId: equipment.parentEquipmentId ?? null,
      plant: equipment.plant,
      properties,
    };
  }

  private readonly logger = new AppLogger(EquipmentClassCrudService.name);

  public constructor(
    @InjectRepository(EquipmentClass)
    private readonly equipmentClassRepository: Repository<EquipmentClass>,
    @InjectRepository(EquipmentClassDescription)
    private readonly equipmentClassDescriptionRepository: Repository<EquipmentClassDescription>,
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  private applyEquipmentClassUpdates(
    equipmentClass: EquipmentClass,
    payload: UpdateEquipmentClassDto,
  ): EquipmentClass {
    try {
      const updated = equipmentClass;
      if (payload.code !== undefined) {
        updated.code = updated.isCustom
          ? buildCustomCode(payload.code)
          : payload.code;
      }
      return updated;
    } catch (error) {
      this.logger.error(
        `Error applying updates to equipment class ${equipmentClass.id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      throw error;
    }
  }

  private async upsertDescription(
    equipmentClassId: number,
    description: string,
    languageCode?: string,
  ): Promise<void> {
    const code = (languageCode ?? 'EN').toUpperCase();

    const existingDescription =
      await this.equipmentClassDescriptionRepository.findOne({
        where: {
          code,
          equipmentClassId,
        },
      });

    if (existingDescription) {
      existingDescription.description = description;
      await this.equipmentClassDescriptionRepository.save(existingDescription);
      return;
    }

    const equipmentClassDescription =
      this.equipmentClassDescriptionRepository.create({
        code,
        description,
        equipmentClassId,
      });

    await this.equipmentClassDescriptionRepository.save(
      equipmentClassDescription,
    );
  }

  public async createWithDescription(
    payload: CreateEquipmentClassWithDescriptionDto,
  ): Promise<EquipmentClass | undefined> {
    const customCode = buildCustomCode(payload.className);
    const existingEquipmentClass = await this.equipmentClassRepository.findOne({
      where: { code: customCode },
    });

    if (existingEquipmentClass) {
      this.logger.warn(
        `Equipment class with code ${customCode} already exists`,
      );
      return undefined;
    }

    const equipmentClass = this.equipmentClassRepository.create({
      code: customCode,
      isCustom: true,
    });

    const savedEquipmentClass =
      await this.equipmentClassRepository.save(equipmentClass);

    try {
      await this.upsertDescription(
        savedEquipmentClass.id,
        payload.description,
        payload.descriptionLanguageCode,
      );
    } catch (error) {
      this.logger.error(
        `Error creating description for equipment class ${savedEquipmentClass.id}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return undefined;
    }

    return savedEquipmentClass;
  }

  public async findAll(): Promise<Array<EquipmentClass>> {
    return this.equipmentClassRepository.find({
      order: { id: 'ASC' },
    });
  }

  public async findEquipmentClasses(
    pagination: PaginationDto,
    language?: string,
  ): Promise<PaginatedResponseDto<EquipmentClass>> {
    const lang = (language ?? 'EN').toUpperCase();

    const query = this.equipmentClassRepository
      .createQueryBuilder('ec')
      .leftJoinAndSelect('ec.descriptions', 'd', 'd.code = :lang', { lang })
      .loadRelationCountAndMap(
        'ec.equipmentClassPropertiesCount',
        'ec.equipmentClassProperties',
      )
      .orderBy('ec.id', 'ASC')
      .skip(pagination.offset)
      .take(pagination.limit);

    const [data, total] = await query.getManyAndCount();

    return {
      data,
      total,
      limit: pagination.limit,
      offset: pagination.offset,
    };
  }

  public async findOne(id: number): Promise<EquipmentClass | undefined> {
    const equipmentClass = await this.equipmentClassRepository.findOne({
      where: { id },
    });

    if (!equipmentClass) {
      this.logger.warn(`Equipment class with id ${id} not found`);
      return undefined;
    }

    return equipmentClass;
  }

  public async findOneWithRelations(
    id: number,
  ): Promise<EquipmentClass | undefined> {
    const equipmentClass = await this.equipmentClassRepository.findOne({
      where: { id },
      relations: [
        'descriptions',
        'parentInheritances',
        'parentInheritances.parentEquipmentClass',
        'childInheritances',
        'childInheritances.childEquipmentClass',
        'equipmentClassProperties',
        'equipmentClassProperties.descriptions',
        'equipmentClassProperties.propertyDataType',
        'equipmentClassProperties.children',
        'equipmentEquipmentClasses',
        'equipmentEquipmentClasses.equipment',
      ],
    });

    if (!equipmentClass) {
      this.logger.warn(`Equipment class with id ${id} not found`);
      return undefined;
    }

    return equipmentClass;
  }

  public async findRelatedEquipment(
    equipmentClassId: number,
    language?: string,
  ): Promise<Array<EquipmentClassRelatedEquipmentDto> | undefined> {
    const equipmentClass = await this.findOne(equipmentClassId);
    if (!equipmentClass) {
      return undefined;
    }

    const selectedLanguage = (
      language ?? EquipmentClassCrudService.defaultDescriptionLanguageCode
    )
      .trim()
      .toUpperCase();

    const links = await this.equipmentEquipmentClassRepository.find({
      where: { equipmentClassId },
      order: {
        equipmentId: 'ASC',
      },
      relations: [
        'equipment',
        'equipment.descriptions',
        'equipment.equipmentLevel',
        'equipment.equipmentProperties',
      ],
    });

    const seenEquipmentIds = new Set<number>();

    return links
      .map((link) => link.equipment)
      .filter(Boolean)
      .filter((equipment) => {
        if (seenEquipmentIds.has(equipment.id)) {
          return false;
        }

        seenEquipmentIds.add(equipment.id);
        return true;
      })
      .map((equipment) =>
        EquipmentClassCrudService.mapEquipmentForClass(
          equipment,
          equipmentClassId,
          selectedLanguage,
        ),
      );
  }

  public async update(
    id: number,
    payload: UpdateEquipmentClassDto,
  ): Promise<EquipmentClass | undefined> {
    const equipmentClass = await this.findOne(id);

    if (!equipmentClass) {
      return undefined;
    }

    const appliedUpdates = this.applyEquipmentClassUpdates(
      equipmentClass,
      payload,
    );
    const updatedClass =
      await this.equipmentClassRepository.save(appliedUpdates);

    if (payload.description !== undefined) {
      try {
        await this.upsertDescription(
          id,
          payload.description,
          payload.descriptionLanguageCode,
        );
      } catch (error) {
        this.logger.error(
          `Error updating description for equipment class ${id}: ${error instanceof Error ? error.message : String(error)}`,
        );
        return undefined;
      }
    }

    return updatedClass;
  }

  public async removeEquipmentClass(id: number): Promise<void> {
    const equipmentClass = await this.findOne(id);
    if (!equipmentClass) {
      return;
    }

    try {
      await this.equipmentClassRepository.manager.transaction(
        async (manager) => {
          const classDescriptionRepository = manager.getRepository(
            EquipmentClassDescription,
          );
          const inheritanceRepository = manager.getRepository(
            EquipmentClassInheritance,
          );
          const classPropertyRepository = manager.getRepository(
            EquipmentClassProperty,
          );
          const propertyDescriptionRepository = manager.getRepository(
            EquipmentPropertyDescription,
          );
          const equipmentClassLinkRepository = manager.getRepository(
            EquipmentEquipmentClass,
          );
          const equipmentPropertyRepository =
            manager.getRepository(EquipmentProperty);
          const equipmentClassRepository =
            manager.getRepository(EquipmentClass);

          await propertyDescriptionRepository
            .createQueryBuilder()
            .delete()
            .from(EquipmentPropertyDescription)
            .where(
              'equipment_class_property_id IN (SELECT id FROM isa95.equipment_class_property WHERE equipment_class_id = :id)',
              { id },
            )
            .execute();
          await classPropertyRepository.delete({ equipmentClassId: id });

          await equipmentPropertyRepository.delete({ equipmentClassId: id });
          await equipmentClassLinkRepository.delete({ equipmentClassId: id });
          await inheritanceRepository
            .createQueryBuilder()
            .delete()
            .from(EquipmentClassInheritance)
            .where('parent_equipment_class_id = :id', { id })
            .orWhere('child_equipment_class_id = :id', { id })
            .execute();
          await classDescriptionRepository.delete({ equipmentClassId: id });
          await equipmentClassRepository.delete({ id });
        },
      );
    } catch (error) {
      this.logger.error(
        `Error cascade deleting equipment class ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}

