import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreateEquipmentClassPropertyDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-class-property.dto';
import { EquipmentClassPropertySemanticsTransformerDto } from '@/modules/isa95-equipment-model/dtos/equipment-class-property-semantics-transformer.dto';
import { UpdateEquipmentClassPropertyDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-class-property.dto';
import { EquipmentPropertyDescription } from '@/modules/isa95-equipment-model/equipment/equipment-property-description/equipment-property-description.entity';
import { EquipmentClassProperty } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-property/equipment-class-property.entity';
import { buildCustomCode } from '@/modules/isa95-equipment-model/utils/custom-code.util';

interface LocalizedDescription {
  code: string;
  description: string;
}

@Injectable()
export class EquipmentClassPropertyCrudService {
  private static extractPropertyDescription(
    property: EquipmentClassProperty,
    languageCode = 'EN',
  ): string | null {
    const descriptions =
      (property.descriptions as Array<LocalizedDescription> | undefined) ?? [];
    const lang = languageCode.toUpperCase();
    const requestedDescription = descriptions.find(
      (description) => description.code === lang,
    )?.description;
    const fallbackDescription = descriptions[0]?.description;

    return requestedDescription ?? fallbackDescription ?? null;
  }

  private static normalizeProperty(
    property: EquipmentClassProperty,
    languageCode = 'EN',
  ): EquipmentClassProperty {
    return {
      ...property,
      description: EquipmentClassPropertyCrudService.extractPropertyDescription(
        property,
        languageCode,
      ),
      propertySemanticsJson:
        EquipmentClassPropertySemanticsTransformerDto.toApi(
          property.propertySemanticsJson,
        ),
      propertyDataType: property.propertyDataType
        ? {
            id: property.propertyDataType.id,
            code: property.propertyDataType.code,
          }
        : undefined,
    } as unknown as EquipmentClassProperty;
  }

  private readonly logger = new AppLogger(
    EquipmentClassPropertyCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentClassProperty)
    private readonly equipmentClassPropertyRepository: Repository<EquipmentClassProperty>,
    @InjectRepository(EquipmentPropertyDescription)
    private readonly equipmentPropertyDescriptionRepository: Repository<EquipmentPropertyDescription>,
  ) {}

  private async upsertDescription(
    equipmentClassPropertyId: number,
    description: string,
    languageCode = 'EN',
  ): Promise<void> {
    const code = languageCode.toUpperCase();
    const existing = await this.equipmentPropertyDescriptionRepository.findOne({
      where: {
        code,
        equipmentClassPropertyId,
      },
    });

    if (existing) {
      existing.description = description;
      await this.equipmentPropertyDescriptionRepository.save(existing);
      return;
    }

    const nextDescription = this.equipmentPropertyDescriptionRepository.create({
      code,
      description,
      equipmentClassPropertyId,
    });
    await this.equipmentPropertyDescriptionRepository.save(nextDescription);
  }

  private async findOneEntity(
    id: number,
  ): Promise<EquipmentClassProperty | undefined> {
    const equipmentClassProperty =
      await this.equipmentClassPropertyRepository.findOne({
        where: { id },
      });

    if (!equipmentClassProperty) {
      this.logger.warn(`Equipment class property with id ${id} not found`);
      return undefined;
    }

    return equipmentClassProperty;
  }

  public async create(
    payload: CreateEquipmentClassPropertyDto,
  ): Promise<EquipmentClassProperty | undefined> {
    const customCode = buildCustomCode(payload.code);
    const existingEquipmentClassProperty =
      await this.equipmentClassPropertyRepository.findOne({
        where: {
          code: customCode,
          equipmentClassId: payload.equipmentClassId,
        },
      });

    if (existingEquipmentClassProperty) {
      this.logger.warn(
        `Equipment class property with code ${customCode} already exists`,
      );
      return undefined;
    }

    const equipmentClassProperty = this.equipmentClassPropertyRepository.create(
      {
        ...payload,
        code: customCode,
        isCustom: true,
        propertySemanticsJson:
          EquipmentClassPropertySemanticsTransformerDto.toDatabase(
            payload.propertySemanticsJson,
          ),
      },
    );
    const createdProperty = await this.equipmentClassPropertyRepository.save(
      equipmentClassProperty,
    );

    if (payload.description?.trim()) {
      await this.upsertDescription(
        createdProperty.id,
        payload.description.trim(),
        payload.descriptionCode ?? 'EN',
      );
    }

    return this.findOne(createdProperty.id);
  }

  public async findAll(): Promise<Array<EquipmentClassProperty>> {
    const properties = await this.equipmentClassPropertyRepository.find({
      relations: {
        descriptions: true,
        propertyDataType: true,
      },
      order: { id: 'ASC' },
    });

    return properties.map((property) =>
      EquipmentClassPropertyCrudService.normalizeProperty(property),
    );
  }

  public async findByEquipmentClassId(
    equipmentClassId: number,
    language = 'EN',
  ): Promise<Array<EquipmentClassProperty>> {
    const properties = await this.equipmentClassPropertyRepository.find({
      relations: {
        descriptions: true,
        propertyDataType: true,
      },
      where: { equipmentClassId },
      order: { id: 'ASC' },
    });

    return properties.map((property) =>
      EquipmentClassPropertyCrudService.normalizeProperty(property, language),
    );
  }

  public async findOne(
    id: number,
  ): Promise<EquipmentClassProperty | undefined> {
    const equipmentClassProperty =
      await this.equipmentClassPropertyRepository.findOne({
        relations: {
          descriptions: true,
          propertyDataType: true,
        },
        where: { id },
      });

    if (!equipmentClassProperty) {
      this.logger.warn(`Equipment class property with id ${id} not found`);
      return undefined;
    }

    return EquipmentClassPropertyCrudService.normalizeProperty(
      equipmentClassProperty,
    );
  }

  public async update(
    id: number,
    payload: UpdateEquipmentClassPropertyDto,
  ): Promise<EquipmentClassProperty | undefined> {
    const equipmentClassProperty = await this.findOneEntity(id);

    if (!equipmentClassProperty) {
      return undefined;
    }

    if (payload.code !== undefined) {
      equipmentClassProperty.code = equipmentClassProperty.isCustom
        ? buildCustomCode(payload.code)
        : payload.code;
    }

    if (payload.propertySemanticsJson !== undefined) {
      equipmentClassProperty.propertySemanticsJson =
        EquipmentClassPropertySemanticsTransformerDto.toDatabase(
          payload.propertySemanticsJson,
        ) ?? payload.propertySemanticsJson;
    }

    if (payload.description?.trim()) {
      await this.upsertDescription(
        equipmentClassProperty.id,
        payload.description.trim(),
        payload.descriptionCode ?? 'EN',
      );
    }

    if (payload.propertyDataTypeId !== undefined) {
      equipmentClassProperty.propertyDataTypeId = payload.propertyDataTypeId;
    }

    if (payload.equipmentClassId !== undefined) {
      equipmentClassProperty.equipmentClassId = payload.equipmentClassId;
    }

    if (payload.parentEquipmentClassPropertyId !== undefined) {
      equipmentClassProperty.parentEquipmentClassPropertyId =
        payload.parentEquipmentClassPropertyId;
    }

    if (payload.length !== undefined) {
      equipmentClassProperty.length = payload.length;
    }

    if (payload.scale !== undefined) {
      equipmentClassProperty.scale = payload.scale;
    }

    await this.equipmentClassPropertyRepository.save(equipmentClassProperty);
    return this.findOne(id);
  }

  public async remove(id: number): Promise<void> {
    const response =
      await this.equipmentClassPropertyRepository.manager.transaction(
        async (manager) => {
          await manager.getRepository(EquipmentPropertyDescription).delete({
            equipmentClassPropertyId: id,
          });

          await manager
            .getRepository(EquipmentClassProperty)
            .update(
              { parentEquipmentClassPropertyId: id },
              { parentEquipmentClassPropertyId: null as unknown as number },
            );

          return manager.getRepository(EquipmentClassProperty).delete({ id });
        },
      );

    if (!response.affected) {
      this.logger.warn(`Equipment class property with id ${id} not found`);
    }
  }
}

