import { EquipmentDescriptionByLanguage } from '@/modules/isa95-equipment-model/equipment/equipment-description-by-language/equipment-description-by-language.entity';
import { EquipmentLevel } from '@/modules/isa95-equipment-model/equipment/equipment-level/equipment-level.entity';
import { Equipment } from '@/modules/isa95-equipment-model/equipment/equipment.entity';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';
import { EquipmentProperty } from '@/modules/isa95-equipment-model/shared/equipment-property/equipment-property.entity';

@Injectable()
export class EquipmentCrudService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static readonly siteEquipmentLevelCode = 'site';

  private static async collectCascadeDeleteOrder(
    equipmentRepository: Repository<Equipment>,
    rootId: number,
  ): Promise<Array<number>> {
    const rows = await equipmentRepository.query(
      `WITH equipment_tree AS (
        SELECT
          equipment.id,
          equipment.parent_equipment_id,
          0 AS depth
        FROM isa95.equipment AS equipment
        WHERE equipment.id = @0

        UNION ALL

        SELECT
          child.id,
          child.parent_equipment_id,
          tree.depth + 1 AS depth
        FROM isa95.equipment AS child
        INNER JOIN equipment_tree AS tree
          ON child.parent_equipment_id = tree.id
      )
      SELECT id
      FROM equipment_tree
      ORDER BY depth DESC, id DESC
      OPTION (MAXRECURSION 0)`,
      [rootId],
    );

    return rows.map(({ id }: { id: number | string }) => Number(id));
  }

  private readonly logger = new AppLogger(EquipmentCrudService.name);

  public constructor(
    @InjectRepository(Equipment)
    private readonly equipmentRepository: Repository<Equipment>,
    @InjectRepository(EquipmentDescriptionByLanguage)
    private readonly equipmentDescriptionRepository: Repository<EquipmentDescriptionByLanguage>,
    @InjectRepository(EquipmentLevel)
    private readonly equipmentLevelRepository: Repository<EquipmentLevel>,
    @InjectRepository(EquipmentProperty)
    private readonly equipmentPropertyRepository: Repository<EquipmentProperty>,
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  private async resolveParentLevelId(
    equipmentLevelId: number,
  ): Promise<number | undefined> {
    const level = await this.equipmentLevelRepository.findOne({
      where: { id: equipmentLevelId },
    });

    return level?.parentEquipmentLevelId ?? undefined;
  }

  private validateJsonKey(key: string): boolean {
    if (!/^[A-Z_a-z]\w*$/.test(key)) {
      this.logger.warn(
        `Invalid JSON property key "${key}". Keys must start with a letter or underscore and contain only letters, digits, and underscores.`,
      );
      return false;
    }
    return true;
  }

  private async resolveOrCreateEquipmentPropertyId(
    equipment: Equipment,
    equipmentClassId?: number,
  ): Promise<number | undefined> {
    if (equipmentClassId !== undefined) {
      const existingForClass = await this.equipmentPropertyRepository.findOne({
        where: { equipmentId: equipment.id, equipmentClassId },
        order: { id: 'ASC' },
      });

      if (existingForClass) {
        return existingForClass.id;
      }

      const createdForClass = this.equipmentPropertyRepository.create({
        plant: equipment.plant,
        equipmentId: equipment.id,
        equipmentClassId,
        propertiesJson: {},
      });

      const savedForClass =
        await this.equipmentPropertyRepository.save(createdForClass);
      return savedForClass.id;
    }

    const existing = await this.equipmentPropertyRepository.find({
      where: { equipmentId: equipment.id },
      order: { id: 'ASC' },
    });

    if (existing.length === 1) {
      return existing[0].id;
    }

    if (existing.length > 1) {
      return existing[0].id;
    }

    const links = await this.equipmentEquipmentClassRepository.find({
      where: { equipmentId: equipment.id },
      order: { equipmentClassId: 'ASC' },
    });

    if (links.length === 0) {
      this.logger.warn(
        `Cannot create equipment property for equipment ${equipment.id} because no equipment class link exists`,
      );
      return undefined;
    }

    const created = this.equipmentPropertyRepository.create({
      plant: equipment.plant,
      equipmentId: equipment.id,
      equipmentClassId: links[0].equipmentClassId,
      propertiesJson: {},
    });

    const saved = await this.equipmentPropertyRepository.save(created);
    return saved.id;
  }

  private async syncEquipmentClasses(
    equipment: Equipment,
    targetClassIds: Array<number>,
  ): Promise<void> {
    const uniqueTargetClassIds = [...new Set(targetClassIds)];
    const existingLinks = await this.equipmentEquipmentClassRepository.find({
      where: { equipmentId: equipment.id },
      order: { id: 'ASC' },
    });

    const existingClassIds = new Set(
      existingLinks.map((link) => link.equipmentClassId),
    );
    const targetClassIdSet = new Set(uniqueTargetClassIds);

    const toAdd = uniqueTargetClassIds.filter(
      (classId) => !existingClassIds.has(classId),
    );
    const toRemove = existingLinks
      .map((link) => link.equipmentClassId)
      .filter((classId) => !targetClassIdSet.has(classId));

    if (toAdd.length > 0) {
      const linksToCreate = toAdd.map((equipmentClassId) =>
        this.equipmentEquipmentClassRepository.create({
          plant: equipment.plant,
          equipmentId: equipment.id,
          equipmentClassId,
        }),
      );
      await this.equipmentEquipmentClassRepository.save(linksToCreate);
    }

    if (toRemove.length > 0) {
      await this.equipmentEquipmentClassRepository.delete({
        equipmentId: equipment.id,
        equipmentClassId: In(toRemove),
      });
    }
  }

  private async mergeJsonPropertiesByPropertyId(
    propertyId: number,
    properties: Record<string, unknown>,
  ): Promise<void> {
    const entries = Object.entries(properties);
    if (entries.length === 0) {
      return;
    }

    for (const [key] of entries) {
      if (!this.validateJsonKey(key)) {
        return;
      }
    }

    const parameters: Array<unknown> = [];
    let expression = 'properties_json';

    for (const [key, value] of entries) {
      const index = parameters.length;
      if (value !== null && typeof value === 'object') {
        parameters.push(JSON.stringify(value));
        expression = `JSON_MODIFY(${expression}, '$.${key}', JSON_QUERY(@${index}))`;
      } else {
        parameters.push(value);
        expression = `JSON_MODIFY(${expression}, '$.${key}', @${index})`;
      }
    }

    const idIndex = parameters.length;
    parameters.push(propertyId);

    await this.equipmentPropertyRepository.manager.query(
      `UPDATE [isa95].[equipment_property] SET properties_json = ${expression} WHERE id = @${idIndex}`,
      parameters,
    );
  }

  private async applyClassProperties(
    equipment: Equipment,
    classProperties: Array<EquipmentClassPropertiesInputDto>,
  ): Promise<void> {
    await Promise.all(
      classProperties.map(async (entry) => {
        const propertyId = await this.resolveOrCreateEquipmentPropertyId(
          equipment,
          entry.equipmentClassId,
        );

        if (propertyId !== undefined) {
          await this.mergeJsonPropertiesByPropertyId(
            propertyId,
            entry.properties,
          );
        }
      }),
    );
  }

  private async validateCreateWithDetailsPayload(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<void> {
    const equipmentLevel = await this.equipmentLevelRepository.findOne({
      where: { id: payload.equipmentLevelId },
    });

    if (!equipmentLevel) {
      throw new BadRequestException(
        `Equipment level ${payload.equipmentLevelId} does not exist`,
      );
    }

    const normalizedLevelCode = equipmentLevel.code.trim().toLowerCase();
    if (normalizedLevelCode !== EquipmentCrudService.siteEquipmentLevelCode) {
      return;
    }

    if (payload.code.trim() !== String(payload.plant)) {
      throw new BadRequestException(
        'Cannot create a new equipment with level site when Equipment code is different from plant',
      );
    }
  }

  private async upsertDefaultDescription(
    equipmentId: number,
    plant: number,
    description: string,
  ): Promise<void> {
    const existingDescription =
      await this.equipmentDescriptionRepository.findOne({
        where: {
          code: EquipmentCrudService.defaultDescriptionLanguageCode,
          equipmentId,
        },
      });

    if (existingDescription) {
      existingDescription.description = description;
      existingDescription.plant = plant;
      await this.equipmentDescriptionRepository.save(existingDescription);
      return;
    }

    const equipmentDescription = this.equipmentDescriptionRepository.create({
      code: EquipmentCrudService.defaultDescriptionLanguageCode,
      description,
      equipmentId,
      plant,
    });
    await this.equipmentDescriptionRepository.save(equipmentDescription);
  }

  public async create(
    payload: CreateEquipmentDto,
  ): Promise<Equipment | undefined> {
    const existingEquipment = await this.equipmentRepository.findOne({
      where: {
        plant: payload.plant,
        code: payload.code,
        equipmentLevelId: payload.equipmentLevelId,
      },
    });

    if (existingEquipment) {
      this.logger.warn(
        `Equipment with plant ${payload.plant}, code ${payload.code}, and equipmentLevelId ${payload.equipmentLevelId} already exists`,
      );
      return undefined;
    }

    const { description, ...equipmentPayload } = payload;
    const equipment = this.equipmentRepository.create(equipmentPayload);
    const savedEquipment = await this.equipmentRepository.save(equipment);

    await this.upsertDefaultDescription(
      savedEquipment.id,
      savedEquipment.plant,
      description,
    );

    return this.findOneWithRelations(savedEquipment.id);
  }

  public async findAll(plant?: number): Promise<Array<Equipment>> {
    return this.equipmentRepository.find({
      order: { id: 'ASC' },
      ...(plant === undefined ? {} : { where: { plant } }),
    });
  }

  public async findAllWithRelations(
    pagination: PaginationDto,
  ): Promise<PaginatedResponseDto<Equipment>> {
    const [data, total] = await this.equipmentRepository.findAndCount({
      order: { id: 'ASC' },
      skip: pagination.offset,
      take: pagination.limit,
      relations: [
        'descriptions',
        'equipmentLevel',
        'parentEquipment',
        'parentEquipment.descriptions',
        'children',
        'children.descriptions',
        'equipmentEquipmentClasses',
        'equipmentEquipmentClasses.equipmentClass',
        'equipmentProperties',
      ],
    });

    return { data, total, limit: pagination.limit, offset: pagination.offset };
  }

  public async findOne(id: number): Promise<Equipment | undefined> {
    const equipment = await this.equipmentRepository.findOne({
      where: { id },
    });

    if (!equipment) {
      this.logger.warn(`Equipment with id ${id} not found`);
      return undefined;
    }

    return equipment;
  }

  public async findParentOptions(
    plant: number,
    equipmentLevelId: number,
  ): Promise<Array<Equipment>> {
    const parentLevelId = await this.resolveParentLevelId(equipmentLevelId);
    if (parentLevelId === undefined) {
      return [];
    }

    return this.equipmentRepository.find({
      where: {
        plant,
        equipmentLevelId: parentLevelId,
      },
      order: { id: 'ASC' },
      relations: ['descriptions', 'equipmentLevel'],
    });
  }

  public async findOneWithRelations(
    id: number,
  ): Promise<Equipment | undefined> {
    const equipment = await this.equipmentRepository.findOne({
      where: { id },
      relations: [
        'descriptions',
        'equipmentLevel',
        'parentEquipment',
        'parentEquipment.descriptions',
        'children',
        'children.descriptions',
        'equipmentEquipmentClasses',
        'equipmentEquipmentClasses.equipmentClass',
        'equipmentProperties',
        'equipmentProperties.equipmentClass',
        'equipmentProperties.equipmentClass.equipmentClassProperties',
      ],
    });

    if (!equipment) {
      this.logger.warn(`Equipment with id ${id} not found`);
      return undefined;
    }

    for (const property of equipment.equipmentProperties ?? []) {
      const json = property.propertiesJson ?? {};
      const semanticsByCode = new Map(
        (property.equipmentClass?.equipmentClassProperties ?? []).map((cp) => [
          cp.code,
          cp,
        ]),
      );

      // Build one enriched entry per propertiesJson key, preserving semantic when available
      const merged = Object.entries(json).map(([key, value]) => {
        const classProperty = semanticsByCode.get(key);
        return {
          ...(classProperty ?? { code: key, propertySemanticsJson: null }),
          value,
        };
      });

      // Replace the raw array with the merged result
      (property as unknown as Record<string, unknown>)['allProperties'] =
        merged;

      if (property.equipmentClass) {
        property.equipmentClass.equipmentClassProperties = [];
      }
    }

    return equipment;
  }

  public async update(
    id: number,
    payload: UpdateEquipmentDto,
  ): Promise<Equipment | undefined> {
    const equipment = await this.findOne(id);

    if (!equipment) {
      return undefined;
    }

    if (payload.plant !== undefined) {
      equipment.plant = payload.plant;
    }

    if (payload.code !== undefined) {
      equipment.code = payload.code;
    }

    if (payload.description !== undefined) {
      await this.upsertDefaultDescription(
        equipment.id,
        payload.plant ?? equipment.plant,
        payload.description,
      );
    }

    if (payload.sapObjId !== undefined) {
      equipment.sapObjId = payload.sapObjId;
    }

    if (payload.equipmentLevelId !== undefined) {
      equipment.equipmentLevelId = payload.equipmentLevelId;
    }

    if (payload.parentEquipmentId !== undefined) {
      equipment.parentEquipmentId = payload.parentEquipmentId;
    }

    if (payload.erpSource !== undefined) {
      equipment.erpSource = payload.erpSource;
    }

    await this.equipmentRepository.save(equipment);
    return this.findOneWithRelations(id);
  }

  public async saveEquipmentDetails(
    id: number,
    payload: SaveEquipmentDetailsDto,
  ): Promise<Equipment | undefined> {
    const {
      classIds,
      classProperties,
      properties,
      propertiesEquipmentClassId,
      ...equipmentData
    } = payload;

    const equipment = await this.findOne(id);
    if (!equipment) {
      return undefined;
    }

    await this.update(id, equipmentData);

    const refreshedEquipment = await this.findOne(id);
    if (!refreshedEquipment) {
      return undefined;
    }

    const classIdsFromProperties = (classProperties ?? []).map(
      (entry) => entry.equipmentClassId,
    );
    const targetClassIds =
      classIds !== undefined || classIdsFromProperties.length > 0
        ? [...new Set([...(classIds ?? []), ...classIdsFromProperties])]
        : undefined;

    if (targetClassIds !== undefined) {
      await this.syncEquipmentClasses(refreshedEquipment, targetClassIds);
    }

    if (properties !== undefined) {
      const propertyId = await this.resolveOrCreateEquipmentPropertyId(
        refreshedEquipment,
        propertiesEquipmentClassId,
      );

      if (propertyId === undefined) {
        return undefined;
      }

      await this.mergeJsonPropertiesByPropertyId(propertyId, properties);
    }

    if (classProperties !== undefined && classProperties.length > 0) {
      await this.applyClassProperties(refreshedEquipment, classProperties);
    }

    return this.findOneWithRelations(id);
  }

  public async createWithDetails(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<Equipment | undefined> {
    await this.validateCreateWithDetailsPayload(payload);

    const {
      classIds,
      classProperties,
      properties,
      propertiesEquipmentClassId,
      ...basePayload
    } = payload;

    const equipment = await this.create(basePayload);
    if (!equipment) {
      return undefined;
    }

    const classIdsFromProperties = (classProperties ?? []).map(
      (entry) => entry.equipmentClassId,
    );
    const targetClassIds = [
      ...new Set([...(classIds ?? []), ...classIdsFromProperties]),
    ];

    if (targetClassIds.length > 0) {
      await this.syncEquipmentClasses(equipment, targetClassIds);
    }

    if (properties !== undefined) {
      const propertyId = await this.resolveOrCreateEquipmentPropertyId(
        equipment,
        propertiesEquipmentClassId,
      );

      if (propertyId !== undefined) {
        await this.mergeJsonPropertiesByPropertyId(propertyId, properties);
      }
    }

    if (classProperties !== undefined && classProperties.length > 0) {
      await this.applyClassProperties(equipment, classProperties);
    }

    return this.findOneWithRelations(equipment.id);
  }

  public async remove(id: number): Promise<void> {
    const equipment = await this.findOne(id);
    if (!equipment) {
      return;
    }

    try {
      await this.equipmentRepository.manager.transaction(async (manager) => {
        const equipmentRepository = manager.getRepository(Equipment);
        const descriptionRepository = manager.getRepository(
          EquipmentDescriptionByLanguage,
        );
        const equipmentClassLinkRepository = manager.getRepository(
          EquipmentEquipmentClass,
        );
        const equipmentPropertyRepository =
          manager.getRepository(EquipmentProperty);

        const deleteOrder =
          await EquipmentCrudService.collectCascadeDeleteOrder(
            equipmentRepository,
            id,
          );

        if (deleteOrder.length === 0) {
          return;
        }

        await equipmentPropertyRepository.delete({
          equipmentId: In(deleteOrder),
        });
        await equipmentClassLinkRepository.delete({
          equipmentId: In(deleteOrder),
        });
        await descriptionRepository.delete({ equipmentId: In(deleteOrder) });

        await equipmentRepository.delete({ id: In(deleteOrder) });
      });
    } catch (error) {
      this.logger.error(
        `Error cascade deleting equipment ${id}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}

