type HierarchyChildField =
  | 'area'
  | 'productionLine'
  | 'workCenter'
  | 'workUnit';

interface HierarchyLevelContext {
  childFieldByLevelId: Map<number, HierarchyChildField>;
  lastRank: number;
  rankByLevelId: Map<number, number>;
}

@Injectable()
export class Isa95EquipmentModelService {
  private static readonly defaultDescriptionLanguageCode = 'EN';

  private static readonly childFields: Array<HierarchyChildField> = [
    'area',
    'productionLine',
    'workCenter',
    'workUnit',
  ];

  private static normalizeEquipmentLevelCode(
    equipmentLevelCode: string,
  ): HierarchyChildField | undefined {
    const normalizedCode = equipmentLevelCode.trim().toLowerCase();

    switch (normalizedCode) {
      case 'area': {
        return 'area';
      }
      case 'productionline': {
        return 'productionLine';
      }
      case 'workcenter': {
        return 'workCenter';
      }
      case 'workunit': {
        return 'workUnit';
      }
      default: {
        return undefined;
      }
    }
  }

  private static buildHierarchyLevelContext(
    equipmentLevels: Array<EquipmentLevel>,
  ): HierarchyLevelContext {
    const childFieldByLevelId = new Map<number, HierarchyChildField>();
    const rankByLevelId = new Map<number, number>();
    const orderedLevels = [...equipmentLevels].sort((left, right) => {
      return left.id - right.id;
    });

    for (const [index, equipmentLevel] of orderedLevels.entries()) {
      rankByLevelId.set(equipmentLevel.id, index + 1);

      const childField = Isa95EquipmentModelService.normalizeEquipmentLevelCode(
        equipmentLevel.code,
      );
      if (childField) {
        childFieldByLevelId.set(equipmentLevel.id, childField);
      }
    }

    return {
      childFieldByLevelId,
      lastRank: orderedLevels.length,
      rankByLevelId,
    };
  }

  private static getLevelRank(
    levelId: number,
    hierarchyLevelContext: HierarchyLevelContext,
  ): number {
    return hierarchyLevelContext.rankByLevelId.get(levelId) ?? 99;
  }

  private static getChildFieldForChildLevel(
    levelId: number,
    hierarchyLevelContext: HierarchyLevelContext,
  ): HierarchyChildField | undefined {
    return hierarchyLevelContext.childFieldByLevelId.get(levelId);
  }

  private static getChildFieldForNodeLevel(
    levelId: number,
    hierarchyLevelContext: HierarchyLevelContext,
  ): HierarchyChildField | undefined {
    const nextLevelRank =
      Isa95EquipmentModelService.getLevelRank(levelId, hierarchyLevelContext) +
      1;

    if (nextLevelRank > hierarchyLevelContext.lastRank) {
      return undefined;
    }

    const nextLevelId = [...hierarchyLevelContext.rankByLevelId.entries()].find(
      ([, rank]) => rank === nextLevelRank,
    )?.[0];

    if (!nextLevelId) {
      return undefined;
    }

    return Isa95EquipmentModelService.getChildFieldForChildLevel(
      nextLevelId,
      hierarchyLevelContext,
    );
  }

  private static getChildrenArray(
    node: Isa95HierarchyNodeDto,
  ): Array<Isa95HierarchyNodeDto> {
    return Isa95EquipmentModelService.childFields.flatMap((fieldName) => {
      return (
        (node[fieldName] as Array<Isa95HierarchyNodeDto> | undefined) ?? []
      );
    });
  }

  private static withoutEmptyChildren(
    node: Isa95HierarchyNodeDto,
  ): Isa95HierarchyNodeDto {
    const sanitizedNode: Isa95HierarchyNodeDto = {
      code: node.code,
      description: node.description,
      id: node.id,
      levelCode: node.levelCode,
      levelId: node.levelId,
      properties: node.properties,
    };

    for (const field of Isa95EquipmentModelService.childFields) {
      const children = node[field] as Array<Isa95HierarchyNodeDto> | undefined;
      if (children && children.length > 0) {
        sanitizedNode[field] = children.map((child) =>
          Isa95EquipmentModelService.withoutEmptyChildren(child),
        );
      }
    }

    return sanitizedNode;
  }

  private static compareNodes(
    left: Isa95HierarchyNodeDto,
    right: Isa95HierarchyNodeDto,
    hierarchyLevelContext: HierarchyLevelContext,
  ): number {
    const levelRankComparison =
      Isa95EquipmentModelService.getLevelRank(
        left.levelId,
        hierarchyLevelContext,
      ) -
      Isa95EquipmentModelService.getLevelRank(
        right.levelId,
        hierarchyLevelContext,
      );

    if (levelRankComparison !== 0) {
      return levelRankComparison;
    }

    const codeComparison = left.code.localeCompare(right.code);
    if (codeComparison !== 0) {
      return codeComparison;
    }

    return left.id - right.id;
  }

  private static sortHierarchy(
    nodes: Array<Isa95HierarchyNodeDto>,
    hierarchyLevelContext: HierarchyLevelContext,
  ): Array<Isa95HierarchyNodeDto> {
    nodes.sort((left, right) => {
      return Isa95EquipmentModelService.compareNodes(
        left,
        right,
        hierarchyLevelContext,
      );
    });

    for (const node of nodes) {
      const children = Isa95EquipmentModelService.getChildrenArray(node);
      if (children.length > 0) {
        Isa95EquipmentModelService.sortHierarchy(
          children,
          hierarchyLevelContext,
        );
      }
    }

    return nodes;
  }

  private static toDescriptionOnlyNode(
    node: Isa95HierarchyNodeDto,
  ): Isa95HierarchyDescriptionNodeDto {
    const result: Isa95HierarchyDescriptionNodeDto = {
      code: node.code,
      description: node.description,
      displayLabel: `${node.code} - ${node.description}`,
    };

    if (node.area && node.area.length > 0) {
      result.area = node.area.map((child) =>
        Isa95EquipmentModelService.toDescriptionOnlyNode(child),
      );
    }

    if (node.productionLine && node.productionLine.length > 0) {
      result.productionLine = node.productionLine.map((child) =>
        Isa95EquipmentModelService.toDescriptionOnlyNode(child),
      );
    }

    if (node.workCenter && node.workCenter.length > 0) {
      result.workCenter = node.workCenter.map((child) =>
        Isa95EquipmentModelService.toDescriptionOnlyNode(child),
      );
    }

    if (node.workUnit && node.workUnit.length > 0) {
      result.workUnit = node.workUnit.map((child) =>
        Isa95EquipmentModelService.toDescriptionOnlyNode(child),
      );
    }

    return result;
  }

  private static withAncestorEquipmentIds(
    sourceIds: Set<number>,
    equipmentById: Map<
      number,
      {
        parentEquipmentId: number | null;
      }
    >,
  ): Set<number> {
    const result = new Set<number>(sourceIds);

    for (const id of sourceIds) {
      let currentParentId = equipmentById.get(id)?.parentEquipmentId;
      while (currentParentId !== null && currentParentId !== undefined) {
        if (result.has(currentParentId)) {
          break;
        }

        result.add(currentParentId);
        currentParentId = equipmentById.get(currentParentId)?.parentEquipmentId;
      }
    }

    return result;
  }

  private static parsePropertiesJson(
    propertiesJson: Record<string, unknown> | string,
  ): Record<string, unknown> {
    if (typeof propertiesJson !== 'string') {
      return propertiesJson;
    }

    return JSON.parse(propertiesJson) as Record<string, unknown>;
  }

  private static addEquipmentIfNew(
    row: {
      classCode: string | null;
      classId: number | null;
      classIsCustom: boolean | null;
      code: string;
      descriptionByLanguage: string | null;
      descriptionLanguageCode: string | null;
      equipmentLevelCode: string;
      equipmentLevelId: number;
      erpSource: string;
      id: number;
      parentEquipmentId: number | null;
      plant: string;
      propertiesJson: PropertiesJsonType;
      propertyId: number | null;
      sapObjId: number;
    },
    equipmentById: Map<
      number,
      {
        code: string;
        description: string;
        equipmentLevelCode: string;
        equipmentLevelId: number;
        erpSource: string;
        id: number;
        parentEquipmentId: number | null;
        plant: string;
        sapObjId: number;
      }
    >,
    childEquipmentIdsByParentId: Map<number, Array<number>>,
  ): void {
    if (equipmentById.has(row.id)) {
      return;
    }

    equipmentById.set(row.id, {
      code: row.code,
      description: row.descriptionByLanguage ?? '',
      equipmentLevelCode: row.equipmentLevelCode,
      equipmentLevelId: row.equipmentLevelId,
      erpSource: row.erpSource,
      id: row.id,
      parentEquipmentId: row.parentEquipmentId,
      plant: row.plant,
      sapObjId: row.sapObjId,
    });

    if (row.parentEquipmentId !== null) {
      const children =
        childEquipmentIdsByParentId.get(row.parentEquipmentId) ?? [];
      children.push(row.id);
      childEquipmentIdsByParentId.set(row.parentEquipmentId, children);
    }
  }

  private static updateEquipmentDescription(
    row: {
      classCode: string | null;
      classId: number | null;
      classIsCustom: boolean | null;
      code: string;
      descriptionByLanguage: string | null;
      descriptionLanguageCode: string | null;
      equipmentLevelCode: string;
      equipmentLevelId: number;
      erpSource: string;
      id: number;
      parentEquipmentId: number | null;
      plant: string;
      propertiesJson: PropertiesJsonType;
      propertyId: number | null;
      sapObjId: number;
    },
    equipmentById: Map<
      number,
      {
        code: string;
        description: string;
        equipmentLevelCode: string;
        equipmentLevelId: number;
        erpSource: string;
        id: number;
        parentEquipmentId: number | null;
        plant: string;
        sapObjId: number;
      }
    >,
  ): void {
    const equipment = equipmentById.get(row.id);
    if (!equipment || row.descriptionByLanguage === null) {
      return;
    }

    const isPreferredLanguage =
      row.descriptionLanguageCode ===
      Isa95EquipmentModelService.defaultDescriptionLanguageCode;
    if (equipment.description.length === 0 || isPreferredLanguage) {
      equipment.description = row.descriptionByLanguage;
    }
  }

  private static addEquipmentClass(
    row: {
      classCode: string | null;
      classId: number | null;
      classIsCustom: boolean | null;
      code: string;
      descriptionByLanguage: string | null;
      descriptionLanguageCode: string | null;
      equipmentLevelCode: string;
      equipmentLevelId: number;
      erpSource: string;
      id: number;
      parentEquipmentId: number | null;
      plant: string;
      propertiesJson: PropertiesJsonType;
      propertyId: number | null;
      sapObjId: number;
    },
    equipmentClassMap: Map<
      number,
      Map<number, { code: string; id: number; isCustom: boolean }>
    >,
  ): void {
    if (
      row.classId === null ||
      row.classCode === null ||
      row.classIsCustom === null
    ) {
      return;
    }

    const classesById = equipmentClassMap.get(row.id) ?? new Map();
    if (!classesById.has(row.classId)) {
      classesById.set(row.classId, {
        code: row.classCode,
        id: row.classId,
        isCustom: row.classIsCustom,
      });
      equipmentClassMap.set(row.id, classesById);
    }
  }

  private static addEquipmentProperty(
    row: {
      classCode: string | null;
      classId: number | null;
      classIsCustom: boolean | null;
      code: string;
      descriptionByLanguage: string | null;
      descriptionLanguageCode: string | null;
      equipmentLevelCode: string;
      equipmentLevelId: number;
      erpSource: string;
      id: number;
      parentEquipmentId: number | null;
      plant: string;
      propertiesJson: PropertiesJsonType;
      propertyId: number | null;
      sapObjId: number;
    },
    equipmentPropertyMap: Map<number, Map<number, Isa95HierarchyPropertyDto>>,
  ): void {
    if (row.propertyId === null || row.propertiesJson === null) {
      return;
    }

    const propertiesById = equipmentPropertyMap.get(row.id) ?? new Map();
    if (!propertiesById.has(row.propertyId)) {
      propertiesById.set(row.propertyId, {
        id: row.propertyId,
        propertiesJson: Isa95EquipmentModelService.parsePropertiesJson(
          row.propertiesJson,
        ),
      });
      equipmentPropertyMap.set(row.id, propertiesById);
    }
  }

  private static buildRestrictedHierarchyContextFromJoinedRows(
    rows: Array<{
      classCode: string | null;
      classId: number | null;
      classIsCustom: boolean | null;
      code: string;
      descriptionByLanguage: string | null;
      descriptionLanguageCode: string | null;
      equipmentLevelCode: string;
      equipmentLevelId: number;
      erpSource: string;
      id: number;
      parentEquipmentId: number | null;
      plant: string;
      propertiesJson: PropertiesJsonType;
      propertyId: number | null;
      sapObjId: number;
    }>,
  ): {
    allEquipmentIds: Set<number>;
    childEquipmentIdsByParentId: Map<number, Array<number>>;
    equipmentById: Map<
      number,
      {
        code: string;
        description: string;
        equipmentLevelCode: string;
        equipmentLevelId: number;
        erpSource: string;
        id: number;
        parentEquipmentId: number | null;
        plant: string;
        sapObjId: number;
      }
    >;
    equipmentClassByEquipmentId: Map<
      number,
      Array<{ code: string; id: number; isCustom: boolean }>
    >;
    equipmentPropertiesByEquipmentId: Map<
      number,
      Array<Isa95HierarchyPropertyDto>
    >;
  } {
    const equipmentById = new Map<
      number,
      {
        code: string;
        description: string;
        equipmentLevelCode: string;
        equipmentLevelId: number;
        erpSource: string;
        id: number;
        parentEquipmentId: number | null;
        plant: string;
        sapObjId: number;
      }
    >();
    const childEquipmentIdsByParentId = new Map<number, Array<number>>();
    const equipmentClassMap = new Map<
      number,
      Map<number, { code: string; id: number; isCustom: boolean }>
    >();
    const equipmentPropertyMap = new Map<
      number,
      Map<number, Isa95HierarchyPropertyDto>
    >();

    for (const row of rows) {
      Isa95EquipmentModelService.addEquipmentIfNew(
        row,
        equipmentById,
        childEquipmentIdsByParentId,
      );
      Isa95EquipmentModelService.updateEquipmentDescription(row, equipmentById);
      Isa95EquipmentModelService.addEquipmentClass(row, equipmentClassMap);
      Isa95EquipmentModelService.addEquipmentProperty(
        row,
        equipmentPropertyMap,
      );
    }

    const equipmentClassByEquipmentId = new Map<
      number,
      Array<{ code: string; id: number; isCustom: boolean }>
    >();
    for (const [equipmentId, classesById] of equipmentClassMap.entries()) {
      equipmentClassByEquipmentId.set(equipmentId, [...classesById.values()]);
    }

    const equipmentPropertiesByEquipmentId = new Map<
      number,
      Array<Isa95HierarchyPropertyDto>
    >();
    for (const [
      equipmentId,
      propertiesById,
    ] of equipmentPropertyMap.entries()) {
      equipmentPropertiesByEquipmentId.set(equipmentId, [
        ...propertiesById.values(),
      ]);
    }

    return {
      allEquipmentIds: new Set<number>(equipmentById.keys()),
      childEquipmentIdsByParentId,
      equipmentById,
      equipmentClassByEquipmentId,
      equipmentPropertiesByEquipmentId,
    };
  }

  private static buildNodesById(
    finalEquipmentIds: Set<number>,
    equipmentById: Map<number, unknown>,
    equipmentPropertiesByEquipmentId: Map<
      number,
      Array<Isa95HierarchyPropertyDto>
    >,
    hierarchyLevelContext: HierarchyLevelContext,
  ): Map<number, Isa95HierarchyNodeDto> {
    const nodesById = new Map<number, Isa95HierarchyNodeDto>();

    for (const id of finalEquipmentIds) {
      const equipment = equipmentById.get(id) as
        | {
            code: string;
            description: string;
            equipmentLevelCode: string;
            equipmentLevelId: number;
            id: number;
          }
        | undefined;

      if (equipment) {
        const node: Isa95HierarchyNodeDto = {
          code: equipment.code,
          description: equipment.description,
          id: equipment.id,
          levelCode: equipment.equipmentLevelCode,
          levelId: equipment.equipmentLevelId,
          properties: equipmentPropertiesByEquipmentId.get(id) ?? [],
        };

        const childrenFieldName =
          Isa95EquipmentModelService.getChildFieldForNodeLevel(
            equipment.equipmentLevelId,
            hierarchyLevelContext,
          );
        if (childrenFieldName) {
          (node[childrenFieldName] as Array<Isa95HierarchyNodeDto>) = [];
        }

        nodesById.set(id, node);
      }
    }

    return nodesById;
  }

  private static buildHierarchyRelationships(
    nodesById: Map<number, Isa95HierarchyNodeDto>,
    equipmentById: Map<number, { parentEquipmentId: number | null }>,
    hierarchyLevelContext: HierarchyLevelContext,
  ): void {
    for (const node of nodesById.values()) {
      Isa95EquipmentModelService.linkNodeToParent(
        node,
        nodesById,
        equipmentById,
        hierarchyLevelContext,
      );
    }
  }

  private static linkNodeToParent(
    node: Isa95HierarchyNodeDto,
    nodesById: Map<number, Isa95HierarchyNodeDto>,
    equipmentById: Map<number, { parentEquipmentId: number | null }>,
    hierarchyLevelContext: HierarchyLevelContext,
  ): void {
    if (
      Isa95EquipmentModelService.getLevelRank(
        node.levelId,
        hierarchyLevelContext,
      ) === 1
    ) {
      return;
    }

    const equipment = equipmentById.get(node.id);
    if (!equipment?.parentEquipmentId) {
      return;
    }

    const parent = nodesById.get(equipment.parentEquipmentId);
    if (!parent) {
      return;
    }

    const childrenFieldName =
      Isa95EquipmentModelService.getChildFieldForChildLevel(
        node.levelId,
        hierarchyLevelContext,
      );
    if (!childrenFieldName) {
      return;
    }
    const childrenArray = parent[childrenFieldName] as
      | Array<Isa95HierarchyNodeDto>
      | undefined;

    if (childrenArray) {
      childrenArray.push(node);
    }
  }

  private static selectRoots(
    nodesById: Map<number, Isa95HierarchyNodeDto>,
    isEquipmentCodeFilter: boolean,
    hierarchyLevelContext: HierarchyLevelContext,
  ): Array<Isa95HierarchyNodeDto> {
    const roots: Array<Isa95HierarchyNodeDto> = [];

    if (isEquipmentCodeFilter) {
      for (const node of nodesById.values()) {
        roots.push(Isa95EquipmentModelService.withoutEmptyChildren(node));
      }
    } else {
      for (const node of nodesById.values()) {
        if (
          Isa95EquipmentModelService.getLevelRank(
            node.levelId,
            hierarchyLevelContext,
          ) === 1
        ) {
          roots.push(node);
        }
      }
    }

    return roots;
  }

  private readonly logger = new AppLogger(Isa95EquipmentModelService.name);

  public constructor(
    @InjectRepository(Equipment)
    private readonly equipmentRepository: Repository<Equipment>,
    @InjectRepository(EquipmentLevel)
    private readonly equipmentLevelRepository: Repository<EquipmentLevel>,
    @InjectRepository(EquipmentDescriptionByLanguage)
    private readonly equipmentDescriptionRepository: Repository<EquipmentDescriptionByLanguage>,
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
    @InjectRepository(EquipmentProperty)
    private readonly equipmentPropertyRepository: Repository<EquipmentProperty>,
  ) {}

  public async getRestrictedHierarchy(
    plant: string,
  ): Promise<Array<Isa95HierarchyNodeDto>> {
    try {
      const rows = await this.getRestrictedHierarchyRowsByDescription(plant);
      const hierarchyLevels = await this.equipmentLevelRepository.find({
        order: { id: 'ASC' },
      });

      if (rows.length === 0 || hierarchyLevels.length === 0) {
        return [];
      }

      const hierarchyLevelContext =
        Isa95EquipmentModelService.buildHierarchyLevelContext(hierarchyLevels);

      const {
        allEquipmentIds,
        equipmentById,
        equipmentPropertiesByEquipmentId,
      } =
        Isa95EquipmentModelService.buildRestrictedHierarchyContextFromJoinedRows(
          rows,
        );

      const nodesById = Isa95EquipmentModelService.buildNodesById(
        allEquipmentIds,
        equipmentById,
        equipmentPropertiesByEquipmentId,
        hierarchyLevelContext,
      );

      Isa95EquipmentModelService.buildHierarchyRelationships(
        nodesById,
        equipmentById,
        hierarchyLevelContext,
      );

      const roots = Isa95EquipmentModelService.selectRoots(
        nodesById,
        false,
        hierarchyLevelContext,
      );

      return Isa95EquipmentModelService.sortHierarchy(
        roots,
        hierarchyLevelContext,
      );
    } catch (error) {
      this.logger.error(
        `Error getting restricted ISA95 hierarchy: ${error instanceof Error ? error.message : String(error)}`,
      );
      return [];
    }
  }

  public async getRestrictedHierarchyDescriptions(
    plant: string,
  ): Promise<Array<Isa95HierarchyDescriptionNodeDto>> {
    const hierarchy = await this.getRestrictedHierarchy(plant);
    return hierarchy.map((node) =>
      Isa95EquipmentModelService.toDescriptionOnlyNode(node),
    );
  }

  public async getRestrictedHierarchyRowsWithDetailsFlat(
    plant: string,
    limit = 50,
    offset = 0,
  ): Promise<RestrictedHierarchyFlatPaginatedResponse | undefined> {
    const safeLimit = Number.isNaN(limit)
      ? 50
      : Math.min(Math.max(limit, 1), 500);
    const safeOffset = Number.isNaN(offset) || offset < 0 ? 0 : offset;

    try {
      const allRows = await this.getRestrictedHierarchyRowsWithDetails(plant);
      const total = allRows.length;
      const data = allRows.slice(safeOffset, safeOffset + safeLimit);

      return {
        data,
        limit: safeLimit,
        offset: safeOffset,
        total,
      };
    } catch (error) {
      this.logger.error(
        `Error getting flat restricted ISA95 hierarchy rows: ${error instanceof Error ? error.message : String(error)}`,
      );
      return undefined;
    }
  }

  private buildRestrictedHierarchyRowsQueryBuilder(
    plant: string,
  ): SelectQueryBuilder<Equipment> {
    return this.equipmentRepository
      .createQueryBuilder('equipment')
      .leftJoin(
        EquipmentLevel,
        'equipment_level',
        'equipment_level.id = equipment.equipment_level_id',
      )
      .leftJoin(
        EquipmentDescriptionByLanguage,
        'equipment_description_by_language',
        'equipment_description_by_language.equipment_id = equipment.id',
      )
      .leftJoin(
        EquipmentEquipmentClass,
        'equipment_equipment_class',
        'equipment_equipment_class.equipment_id = equipment.id AND equipment_equipment_class.plant = equipment.plant',
      )
      .leftJoin(
        EquipmentClass,
        'equipment_class',
        'equipment_class.id = equipment_equipment_class.equipment_class_id',
      )
      .leftJoin(
        EquipmentProperty,
        'equipment_property',
        'equipment_property.equipment_id = equipment.id AND equipment_property.plant = equipment.plant',
      )
      .where('equipment.plant = :plant', { plant });
  }

  private buildRestrictedHierarchyRowsQueryBuilderByDescription(
    plant: string,
  ): SelectQueryBuilder<Equipment> {
    return this.equipmentRepository
      .createQueryBuilder('equipment')
      .leftJoin(
        EquipmentLevel,
        'equipment_level',
        'equipment_level.id = equipment.equipment_level_id',
      )
      .leftJoin(
        EquipmentDescriptionByLanguage,
        'equipment_description_by_language',
        'equipment_description_by_language.equipment_id = equipment.id',
      )
      .where('equipment.plant = :plant', { plant });
  }

  private async getRestrictedHierarchyRowsWithDetails(
    plant: string,
  ): Promise<Array<RestrictedHierarchyFlatRow>> {
    const queryBuilder = this.buildRestrictedHierarchyRowsQueryBuilder(plant)
      .select([
        'equipment.id AS id',
        'equipment.code AS code',
        'equipment.sap_obj_id AS sapObjId',
        'equipment.plant AS plant',
        'equipment.erp_source AS erpSource',
        'equipment.parent_equipment_id AS parentEquipmentId',
        'equipment_level.id AS equipmentLevelId',
        'equipment_level.code AS equipmentLevelCode',
        'equipment_description_by_language.code AS descriptionLanguageCode',
        'equipment_description_by_language.description AS descriptionByLanguage',
        'equipment_class.id AS classId',
        'equipment_class.code AS classCode',
        'equipment_class.is_custom AS classIsCustom',
        'equipment_property.id AS propertyId',
        'equipment_property.properties_json AS propertiesJson',
      ])
      .orderBy('equipment.id', 'ASC')
      .addOrderBy('equipment_description_by_language.code', 'ASC')
      .addOrderBy('equipment_class.id', 'ASC')
      .addOrderBy('equipment_property.id', 'ASC');

    return queryBuilder.getRawMany<RestrictedHierarchyFlatRow>();
  }

  private async getRestrictedHierarchyRowsByDescription(
    plant: string,
  ): Promise<Array<RestrictedHierarchyFlatRow>> {
    const queryBuilder =
      this.buildRestrictedHierarchyRowsQueryBuilderByDescription(plant)
        .select([
          'equipment.id AS id',
          'equipment.code AS code',
          'equipment.plant AS plant',
          'equipment.parent_equipment_id AS parentEquipmentId',
          'equipment_level.id AS equipmentLevelId',
          'equipment_level.code AS equipmentLevelCode',
          'equipment_description_by_language.code AS descriptionLanguageCode',
          'equipment_description_by_language.description AS descriptionByLanguage',
        ])
        .orderBy('equipment.id', 'ASC')
        .addOrderBy('equipment_description_by_language.code', 'ASC')
        .addOrderBy('equipment_level.id', 'ASC');

    return queryBuilder.getRawMany<RestrictedHierarchyFlatRow>();
  }
}

