import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreateEquipmentEquipmentClassDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-equipment-class.dto';
import { EquipmentEquipmentClass } from '@/modules/isa95-equipment-model/shared/equipment-equipment-class/equipment-equipment-class.entity';

@Injectable()
export class EquipmentEquipmentClassCrudService {
  private readonly logger = new AppLogger(
    EquipmentEquipmentClassCrudService.name,
  );

  public constructor(
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
  ) {}

  public async create(
    payload: CreateEquipmentEquipmentClassDto,
  ): Promise<EquipmentEquipmentClass | undefined> {
    const existing = await this.equipmentEquipmentClassRepository.findOne({
      where: {
        equipmentId: payload.equipmentId,
        equipmentClassId: payload.equipmentClassId,
      },
    });

    if (existing) {
      this.logger.warn(
        `Equipment ${payload.equipmentId} is already linked to class ${payload.equipmentClassId} on plant ${payload.plant}`,
      );
      return undefined;
    }

    const link = this.equipmentEquipmentClassRepository.create(payload);
    return this.equipmentEquipmentClassRepository.save(link);
  }

  public async findAll(): Promise<Array<EquipmentEquipmentClass>> {
    return this.equipmentEquipmentClassRepository.find({
      order: { id: 'ASC' },
    });
  }

  public async findByEquipmentId(
    equipmentId: number,
  ): Promise<Array<EquipmentEquipmentClass>> {
    return this.equipmentEquipmentClassRepository.find({
      where: { equipmentId },
      order: { id: 'ASC' },
    });
  }

  public async findByEquipmentClassId(
    equipmentClassId: number,
  ): Promise<Array<EquipmentEquipmentClass>> {
    return this.equipmentEquipmentClassRepository.find({
      where: { equipmentClassId },
      order: { id: 'ASC' },
    });
  }

  public async findOne(
    id: number,
  ): Promise<EquipmentEquipmentClass | undefined> {
    const link = await this.equipmentEquipmentClassRepository.findOne({
      where: { id },
    });

    if (!link) {
      this.logger.warn(`Equipment-to-class link with id ${id} not found`);
      return undefined;
    }

    return link;
