import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { CreateEquipmentPropertyDto } from '@/modules/isa95-equipment-model/dtos/create-equipment-property.dto';
import { DeleteJsonPropertiesDto } from '@/modules/isa95-equipment-model/dtos/delete-json-properties.dto';
import { PatchJsonPropertiesDto } from '@/modules/isa95-equipment-model/dtos/patch-json-properties.dto';
import { UpdateEquipmentPropertyDto } from '@/modules/isa95-equipment-model/dtos/update-equipment-property.dto';
import { EquipmentProperty } from '@/modules/isa95-equipment-model/shared/equipment-property/equipment-property.entity';

@Injectable()
export class EquipmentPropertyCrudService {
  private readonly logger = new AppLogger(EquipmentPropertyCrudService.name);

  public constructor(
    @InjectRepository(EquipmentProperty)
    private readonly equipmentPropertyRepository: Repository<EquipmentProperty>,
  ) {}

  /**
   * Rejects key names that cannot be safely embedded in a JSON path literal.
   * Allowed: letters, digits, and underscores, starting with a letter or underscore.
   * Returns false and logs a warning when the key is not valid for a SQL JSON path.
   * @param key JSON property key to validate before building a SQL JSON path.
   * @returns `true` when the key is valid; `false` when the key is invalid (warning is logged).
   */
  private validateJsonKey(key: string): boolean {
    if (!/^[A-Z_a-z]\w*$/.test(key)) {
      this.logger.warn(
        `Invalid JSON property key "${key}". Keys must start with a letter or underscore and contain only letters, digits, and underscores.`,
      );
      return false;
    }
    return true;
  }

  public async create(
    payload: CreateEquipmentPropertyDto,
  ): Promise<EquipmentProperty> {
    const equipmentProperty = this.equipmentPropertyRepository.create(payload);
    return this.equipmentPropertyRepository.save(equipmentProperty);
  }

  public async findAll(): Promise<Array<EquipmentProperty>> {
    return this.equipmentPropertyRepository.find({
      order: { id: 'ASC' },
    });
  }

  public async findOne(id: number): Promise<EquipmentProperty | undefined> {
    const equipmentProperty = await this.equipmentPropertyRepository.findOne({
      where: { id },
    });

    if (!equipmentProperty) {
      this.logger.warn(`Equipment property with id ${id} not found`);
      return undefined;
    }

    return equipmentProperty;
  }

  public async update(
    id: number,
    payload: UpdateEquipmentPropertyDto,
  ): Promise<EquipmentProperty | undefined> {
    // Verify the record exists before updating
    const existing = await this.findOne(id);
    if (!existing) {
      return undefined;
    }

    const setClauses: Array<string> = [];
    const parameters: Array<unknown> = [];

    if (payload.plant !== undefined) {
      setClauses.push(`plant = @${parameters.length}`);
      parameters.push(payload.plant);
    }

    if (payload.equipmentId !== undefined) {
      setClauses.push(`equipment_id = @${parameters.length}`);
      parameters.push(payload.equipmentId);
    }

    if (payload.equipmentClassId !== undefined) {
      setClauses.push(`equipment_class_id = @${parameters.length}`);
      parameters.push(payload.equipmentClassId);
    }

    if (payload.propertiesJson !== undefined) {
      // Full replacement of the JSON document — passed as a raw JSON string
      // So SQL Server stores it in the native JSON column without any extra escaping.
      setClauses.push(`properties_json = @${parameters.length}`);
      parameters.push(JSON.stringify(payload.propertiesJson));
    }

    if (setClauses.length > 0) {
      parameters.push(id);
      await this.equipmentPropertyRepository.manager.query(
        `UPDATE [isa95].[equipment_property] SET ${setClauses.join(', ')} WHERE id = @${parameters.length - 1}`,
        parameters,
      );
    }

    return this.findOne(id);
  }

  public async remove(id: number): Promise<void> {
    const response = await this.equipmentPropertyRepository.delete({ id });

    if (!response.affected) {
      this.logger.warn(`Equipment property with id ${id} not found`);
    }
  }

  /**
   * Returns only the requested keys from propertiesJson using OPENJSON.
   * Keys not present in the stored JSON are omitted from the response.
   * @param id Equipment property record identifier.
   * @param keys JSON property keys to extract from the stored document.
   * @returns Object containing only the requested keys that exist in the stored JSON.
   */
  public async getJsonProperties(
    id: number,
    keys: Array<string>,
  ): Promise<Record<string, unknown> | undefined> {
    for (const k of keys) {
      if (!this.validateJsonKey(k)) return undefined;
    }

    // Build: SELECT JSON_VALUE(p.properties_json, '$.K1') AS K1, ...
    const selects = keys
      .map((k) => `JSON_VALUE(p.properties_json, '$.${k}') AS [${k}]`)
      .join(', ');

    const rows: Array<Record<string, string | null>> =
      await this.equipmentPropertyRepository.manager.query(
        `SELECT ${selects} FROM [isa95].[equipment_property] p WHERE p.id = @0`,
        [id],
      );

    if (rows.length === 0) {
      this.logger.warn(`Equipment property with id ${id} not found`);
      return undefined;
    }

    // Filter out keys that had no value in the JSON (JSON_VALUE returns NULL for missing keys)
    return Object.fromEntries(
      Object.entries(rows[0]).filter(([, v]) => v !== null),
    ) as Record<string, unknown>;
  }

  /**
   * Merges specific keys into propertiesJson using SQL Server JSON_MODIFY.
   * Existing keys not listed in the payload are left untouched.
   * Object / array values are wrapped with JSON_QUERY so SQL Server stores
   * them as a JSON sub-document instead of an escaped string.
   * @param id Equipment property record identifier.
   * @param payload Key-value pairs to merge into the stored JSON document.
   * @returns Updated equipment property record after merging the requested keys.
   */
  public async mergeJsonProperties(
    id: number,
    payload: PatchJsonPropertiesDto,
  ): Promise<EquipmentProperty | undefined> {
    const entries = Object.entries(payload.properties);
    if (entries.length === 0) {
      return this.findOne(id);
    }

    for (const [key] of entries) {
      if (!this.validateJsonKey(key)) return undefined;
    }

    // Build a chained JSON_MODIFY expression:
    //   JSON_MODIFY(JSON_MODIFY(properties_json, '$.K1', @0), '$.K2', JSON_QUERY(@1))
    const parameters: Array<unknown> = [];
    let expr = 'properties_json';

    for (const [key, value] of entries) {
      const index = parameters.length;
      if (value !== null && typeof value === 'object') {
        parameters.push(JSON.stringify(value));
        expr = `JSON_MODIFY(${expr}, '$.${key}', JSON_QUERY(@${index}))`;
      } else {
        parameters.push(value);
        expr = `JSON_MODIFY(${expr}, '$.${key}', @${index})`;
      }
    }

    const idIndex = parameters.length;
    parameters.push(id);

    await this.equipmentPropertyRepository.manager.query(
      `UPDATE [isa95].[equipment_property] SET properties_json = ${expr} WHERE id = @${idIndex}`,
      parameters,
    );

    return this.findOne(id);
  }

  /**
   * Removes specific keys from propertiesJson using SQL Server JSON_MODIFY.
   * In SQL Server, passing SQL NULL as the value removes the key from the document.
   * Keys not present in the stored JSON are silently ignored.
   * @param id Equipment property record identifier.
   * @param payload Collection of JSON property keys to remove.
   * @returns Updated equipment property record after removing the requested keys.
   */
  public async deleteJsonProperties(
    id: number,
    payload: DeleteJsonPropertiesDto,
  ): Promise<EquipmentProperty | undefined> {
    if (payload.keys.length === 0) {
      return this.findOne(id);
    }

    for (const k of payload.keys) {
      if (!this.validateJsonKey(k)) return undefined;
    }

    // JSON_MODIFY with SQL NULL removes the key from the document
    let expr = 'properties_json';
    for (const key of payload.keys) {
      expr = `JSON_MODIFY(${expr}, '$.${key}', NULL)`;
    }

    await this.equipmentPropertyRepository.manager.query(
      `UPDATE [isa95].[equipment_property] SET properties_json = ${expr} WHERE id = @0`,
      [id],
    );

    return this.findOne(id);
  }
}

