export const CUSTOM_CODE_PREFIX = 'CUST_';

/**
 *
 * @param code - A string representing a code that may or may not already have the custom code prefix.
 * @returns The function takes a string input `code` and checks if it starts with the prefix defined in `CUSTOM_CODE_PREFIX`. If it does, it returns the code as is. If it doesn't, it prepends the prefix to the code and returns the modified string. This function is useful for ensuring that all custom codes follow a consistent format by adding a specific prefix when necessary.
 */
export function buildCustomCode(code: string): string {
  if (code.startsWith(CUSTOM_CODE_PREFIX)) {
    return code;
  }

  return `${CUSTOM_CODE_PREFIX}${code}`;
}

