import { Readable } from 'node:stream';
import { RedisConnectionService } from '@mesx/common-lib';
import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
  OnModuleInit,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import * as csvParser from 'csv-parser';
import { In, IsNull, Not, Repository } from 'typeorm';
import { CsvdataDto } from './dto/csvdata-dto';
import { PlantDto } from './dto/plant-dto';
import { PlantIngestionResponseDto } from './dto/plant-ingestion-response-dto';
import { PlantResponseDto } from './dto/plant-response-dto';
import { AppLogger } from '@/common/logger/app-logger';
import { EwmPlantMessage } from '@/common/publish-message/interface/publish-event-ewm-plant';
import { PlantMessage } from '@/common/publish-message/interface/publish-plant.interface';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { RedisConfigService } from '@/config/redis/redis-sdk/redis-sdk.service';
import { Plant } from '@/modules/plant/plant.entity';
import { ProductionLine } from '@/modules/production-line/production-line.entity';
import { Resource } from '@/modules/resource/resource.entity';
import { Uap } from '@/modules/uap/uap.entity';
import { Workcenter } from '@/modules/workcenter/workcenter.entity';

@Injectable()
export class PlantService implements OnModuleInit {
  private readonly logger = new AppLogger(PlantService.name);

  public constructor(
    @InjectRepository(Plant)
    private readonly plantRepository: Repository<Plant>,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
    private readonly redisConfigService: RedisConfigService,
    private readonly redisConnectionService: RedisConnectionService,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.processPlantsInRedis();
  }

  public async getPlantById(plantId: number): Promise<Plant> {
    try {
      const plant = await this.plantRepository.findOne({
        where: { plantId },
      });
      if (!plant) {
        throw new NotFoundException('Plant not found');
      }
      return plant;
    } catch (error) {
      throw new InternalServerErrorException('Failed to retrieve plant', error);
    }
  }

  public async getHierarchy(plantId: number): Promise<Array<PlantDto>> {
    const plants = await this.plantRepository
      .createQueryBuilder('plant')
      .leftJoinAndMapMany(
        'plant.uaps',
        Uap,
        'uap',
        'uap.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'uap.productionLines',
        ProductionLine,
        'production_line',
        'production_line.uap_id = uap.uap_id AND production_line.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'production_line.workcenters',
        Workcenter,
        'workcenter',
        'workcenter.prod_line_id = production_line.prod_line_id AND workcenter.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'workcenter.resources',
        Resource,
        'resource',
        'resource.workcenter_id = workcenter.workcenter_id AND resource.plant = plant.plant_id',
      )
      .where('plant.plant_id = :plantId', { plantId })
      .getMany();
    return plants as Array<PlantDto>;
  }

  public async getPlantIds(): Promise<Array<number>> {
    const plants = await this.plantRepository.find({ select: ['plantId'] });
    return plants.map((plant) => plant.plantId);
  }

  public async getPlants(): Promise<Array<PlantIngestionResponseDto>> {
    const result: Array<Plant> = await this.plantRepository.find({
      select: [
        'plantId',
        'languageCode',
        'timezone',
        'plantLink',
        'plantDesc',
        'sapServer',
        'gateway',
        'sid',
      ],
    });
    const plantDtos: Array<PlantIngestionResponseDto> = result.map((plant) => ({
      gateway: plant.gateway,
      languageCode: plant.languageCode,
      plantDesc: plant.plantDesc,
      plantId: plant.plantId,
      plantLink: plant.plantLink,
      sapServer: plant.sapServer,
      sid: plant.sid,
      timeZone: plant.timezone,
    }));

    return plantDtos;
  }

  public async processPlantsInRedis(): Promise<void> {
    try {
      const plants = await this.getPlants();
      await this.savePlantsInRedis(plants);
    } catch (error) {
      this.logger.error(`Error processing plants for Redis: ${error}`);
    }
  }

  private async publishPlantUpdateEvent(
    action: 'create' | 'update' | 'delete',
    plantId?: number,
  ): Promise<void> {
    try {
      const redisClient = await this.redisConnectionService.getClient();
      const channel = 'plants-updated';
      const message = JSON.stringify({
        action,
        plantId: plantId ?? null,
        timestamp: Date.now(),
      });
      await redisClient.publish(channel, message);
      this.logger.log(`Published Redis event on ${channel}: ${message}`);
    } catch (error) {
      this.logger.error('Failed to publish plant update event', error);
    }
  }

  public async savePlantsInRedis(
    plants: Array<PlantIngestionResponseDto>,
  ): Promise<void> {
    const redisKey = this.redisConfigService.redisPlantKey;
    let client;

    try {
      client = await this.redisConnectionService.getClient();
      // Save JSON string in Redis
      await client.hSet(redisKey, 'plants', JSON.stringify(plants));

      this.logger.log(
        `Saved ${plants.length} plants to Redis with key ${redisKey}`,
      );
    } catch (error) {
      this.logger.error(`Failed to save plants in Redis: ${error}`);
      throw error;
    } finally {
      // Release client back to pool if pooling is enabled
      if (client) await this.redisConnectionService.releaseClient(client);
    }
  }

  public async createorupdateFromCsvUploaded(
    fileBuffer: Buffer,
  ): Promise<string> {
    this.logger.log('Service started processing CSV file from buffer');

    const results: Array<CsvdataDto> = [];
    return new Promise((resolve, reject) => {
      const readableStream = Readable.from([fileBuffer]);

      readableStream
        .pipe(csvParser())
        .on('data', (data: CsvdataDto) => {
          results.push(data);
        })
        .on('end', async () => {
          try {
            const updateOrCreatePromises = results.map(async (row) => {
              const existingPlant = await this.plantRepository.findOneBy({
                plantId: row.plantCode,
              });
              if (existingPlant) {
                existingPlant.plantDesc = row.bauShortName;
                existingPlant.plantLink = row.miiServer;
                existingPlant.timezone = row.legalSiteTimeZone;
                existingPlant.sapServer = row.sapServer;
                existingPlant.gateway = row.gateway;
                existingPlant.sid = row.sid;
                await this.plantRepository.save(existingPlant);
              } else {
                const newPlant = this.plantRepository.create({
                  gateway: row.gateway,
                  plantDesc: row.bauShortName,
                  plantId: row.plantCode,
                  plantLink: row.miiServer,
                  sapServer: row.sapServer,
                  sid: row.sid,
                  timezone: row.legalSiteTimeZone,
                });
                await this.plantRepository.save(newPlant);
              }
            });

            // Wait for all promises to complete
            await Promise.all(updateOrCreatePromises);
            await this.processPlantsInRedis();
            await this.publishPlantUpdateEvent('create');
            const message = 'plant hierarchy api plant updated';
            await this.publishPlantMessage(message);

            resolve('success');
          } catch (error) {
            this.logger.error(
              `Failed to process CSV file from buffer: ${error.message}`,
            );
            reject(new Error(error));
          }
        })
        .on('error', (error: Error) => {
          this.logger.error(
            `Error reading CSV file from buffer: ${error.message}`,
          );
          reject(error);
        });
    });
  }

  private async publishPlantMessage(message: string): Promise<void> {
    const plantMessage: PlantMessage = {
      message,
    };
    await this.publishMessageService.publishMessage(
      this.eventhubService.topicPlantHYR,
      plantMessage,
    );
  }

  public async checkDeletedPlant(plantId: number): Promise<boolean> {
    try {
      const existingPlant = await this.plantRepository.findOne({
        where: {
          deletedAt: Not(IsNull()),
          plantId,
        },
        withDeleted: true,
      });
      return !!existingPlant;
    } catch (error) {
      throw new InternalServerErrorException(
        'Failed to check deleted plant',
        error,
      );
    }
  }

  public async addPlant(plantDto: PlantResponseDto): Promise<Plant> {
    const existingPlant = await this.plantRepository.findOne({
      where: {
        deletedAt: Not(IsNull()),
        plantId: plantDto.plantId,
      },
      withDeleted: true,
    });

    if (existingPlant) {
      await this.plantRepository.recover(existingPlant);
      // Safely merge only known fields
      this.plantRepository.merge(existingPlant, {
        ...plantDto,
        bufferization: existingPlant.bufferization ?? false,
      });
      return this.plantRepository.save(existingPlant);
    }

    const newPlant = this.plantRepository.create({
      ...plantDto,
      bufferization: false, // Ensure it's defined
    });
    const result = this.plantRepository.save(newPlant);
    await this.processPlantsInRedis();
    await this.publishPlantUpdateEvent('create', newPlant.plantId);
    return result;
  }

  public async updatePlant(
    plantId: number,
    plantDto: PlantResponseDto,
  ): Promise<Plant> {
    const existingPlant = await this.plantRepository.findOne({
      where: { plantId },
    });

    if (!existingPlant) {
      throw new NotFoundException('Plant not found');
    }

    let isEwmPublish = false;

    if (plantDto.plantDesc !== undefined) {
      existingPlant.plantDesc = plantDto.plantDesc;
    }

    if (plantDto.languageCode !== undefined) {
      existingPlant.languageCode = plantDto.languageCode;
    }

    if (plantDto.plantLink !== undefined) {
      existingPlant.plantLink = plantDto.plantLink;
    }

    if (plantDto.timezone !== undefined) {
      existingPlant.timezone = plantDto.timezone;
    }

    if (plantDto.sid !== undefined) {
      existingPlant.sid = plantDto.sid;
    }

    if (plantDto.ewmFlow !== undefined) {
      isEwmPublish = plantDto.ewmFlow !== existingPlant.ewmFlow;
      existingPlant.ewmFlow = plantDto.ewmFlow;
    }

    if (plantDto.voiceToActEnabled !== undefined) {
      existingPlant.voiceToActEnabled = plantDto.voiceToActEnabled;
    }

    if (plantDto.mleanLink !== undefined) {
      existingPlant.mleanLink = plantDto.mleanLink;
    }

    if (plantDto.downtimeTicketReclassificationThreshold !== undefined) {
      existingPlant.downtimeTicketReclassificationThreshold =
        plantDto.downtimeTicketReclassificationThreshold;
    }
    if (plantDto.secondaryLanguageCode !== undefined) {
      existingPlant.secondaryLanguageCode =
        plantDto.secondaryLanguageCode ?? null;
    }

    const plant = await this.plantRepository.save(existingPlant);
    if (isEwmPublish) {
      const ewmPlantMessage: EwmPlantMessage = {
        message: 'Plant updated',
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicEwmPlants,
        ewmPlantMessage,
      );
    }
    await this.processPlantsInRedis();
    await this.publishPlantUpdateEvent('update', plant.plantId);

    return plant;
  }

  public async deletePlant(plantId: number): Promise<void> {
    const plant = await this.plantRepository.findOne({ where: { plantId } });
    if (!plant) {
      throw new NotFoundException('Plant not found');
    }
    await this.plantRepository.softRemove(plant);
    await this.processPlantsInRedis();
    await this.publishPlantUpdateEvent('delete', plantId);
  }

  public async ewmPlant(): Promise<Array<PlantDto>> {
    try {
      const plants = await this.plantRepository.find({
        select: ['plantId', 'bufferization', 'timezone'],
        where: {
          ewmFlow: true,
        },
      });

      if (plants.length === 0) {
        throw new NotFoundException(`EWM plants not found `);
      }
      return plants;
    } catch (error) {
      this.logger.error(`Failed to retrieve EWM plants : ${error.message}`);

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(`Failed to retrieve EWM plants`);
      }
      throw error;
    }
  }

  public async getRestrictedHierarchy(
    plantId: number,
    attributes?: Record<string, string>,
  ): Promise<Array<PlantDto>> {
    try {
      if (
        !attributes ||
        (!attributes.uap &&
          !attributes.prodline &&
          !attributes.workcenter &&
          !attributes.resource)
      ) {
        return await this.getHierarchy(plantId);
      }

      const queryBuilder = this.plantRepository
        .createQueryBuilder('plant')
        .where('plant.plant_id = :plantId', { plantId });

      if (attributes?.resource) {
        // Get specific resource and its workcenter
        return await this.getResourceHierarchy(plantId, attributes.resource);
      }

      if (attributes?.workcenter) {
        // Get workcenter and everything under it
        queryBuilder
          .leftJoinAndMapMany(
            'plant.uaps',
            Uap,
            'uap',
            'uap.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'uap.productionLines',
            ProductionLine,
            'production_line',
            'production_line.uap_id = uap.uap_id AND production_line.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'production_line.workcenters',
            Workcenter,
            'workcenter',
            'workcenter.prod_line_id = production_line.prod_line_id AND workcenter.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'workcenter.resources',
            Resource,
            'resource',
            'resource.workcenter_id = workcenter.workcenter_id AND resource.plant = plant.plant_id',
          )
          .andWhere('workcenter.workcenter_id = :workcenterId', {
            workcenterId: attributes.workcenter,
          });
      } else if (attributes?.prodline) {
        // Get production line and everything under it
        queryBuilder
          .leftJoinAndMapMany(
            'plant.uaps',
            Uap,
            'uap',
            'uap.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'uap.productionLines',
            ProductionLine,
            'production_line',
            'production_line.uap_id = uap.uap_id AND production_line.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'production_line.workcenters',
            Workcenter,
            'workcenter',
            'workcenter.prod_line_id = production_line.prod_line_id AND workcenter.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'workcenter.resources',
            Resource,
            'resource',
            'resource.workcenter_id = workcenter.workcenter_id AND resource.plant = plant.plant_id',
          )
          .andWhere('production_line.prod_line_id = :prodLineId', {
            prodLineId: attributes.prodline,
          });
      } else if (attributes?.uap) {
        // Get UAP and everything under it
        queryBuilder
          .leftJoinAndMapMany(
            'plant.uaps',
            Uap,
            'uap',
            'uap.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'uap.productionLines',
            ProductionLine,
            'production_line',
            'production_line.uap_id = uap.uap_id AND production_line.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'production_line.workcenters',
            Workcenter,
            'workcenter',
            'workcenter.prod_line_id = production_line.prod_line_id AND workcenter.plant = plant.plant_id',
          )
          .leftJoinAndMapMany(
            'workcenter.resources',
            Resource,
            'resource',
            'resource.workcenter_id = workcenter.workcenter_id AND resource.plant = plant.plant_id',
          )
          .andWhere('uap.uap_id = :uapId', { uapId: attributes.uap });
      }

      return await (queryBuilder.getMany() as Promise<Array<PlantDto>>);
    } catch (error) {
      this.logger.error('Error getting restricted hierarchy:', error);
      throw new InternalServerErrorException(
        'Failed to get restricted hierarchy',
      );
    }
  }

  private async getResourceHierarchy(
    plantId: number,
    resourceId: string,
  ): Promise<Array<PlantDto>> {
    return this.plantRepository
      .createQueryBuilder('plant')
      .leftJoinAndMapMany(
        'plant.uaps',
        Uap,
        'uap',
        'uap.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'uap.productionLines',
        ProductionLine,
        'production_line',
        'production_line.uap_id = uap.uap_id AND production_line.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'production_line.workcenters',
        Workcenter,
        'workcenter',
        'workcenter.prod_line_id = production_line.prod_line_id AND workcenter.plant = plant.plant_id',
      )
      .leftJoinAndMapMany(
        'workcenter.resources',
        Resource,
        'resource',
        'resource.workcenter_id = workcenter.workcenter_id AND resource.plant = plant.plant_id',
      )
      .where('plant.plant_id = :plantId', { plantId })
      .andWhere('resource.resource_id = :resourceId', { resourceId })
      .getMany() as Promise<Array<PlantDto>>;
  }

  public async getSapServerByPlant(
    plantId: number | Array<number>,
  ): Promise<string | Array<string>> {
    try {
      // Normalize input to array
      const plantsArray = Array.isArray(plantId) ? plantId : [plantId];

      // Query the database
      const plants = await this.plantRepository.find({
        where: { plantId: In(plantsArray) },
        select: ['sapServer'],
      });

      if (!plants || plants.length === 0) {
        throw new NotFoundException(
          `SAP server not found for plant(s): ${plantsArray.join(', ')}`,
        );
      }

      // Extract SAP servers
      const sapServers = plants.map((p) => p.sapServer);

      // Return a single string if input was a single plant
      if (!Array.isArray(plantId)) {
        return sapServers[0];
      }

      // Return array of strings for multiple plants
      return sapServers;
    } catch (error) {
      this.logger.error(
        `Error retrieving SAP server for plant(s) ${plantId}: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  public async getDowntimeThresholdByPlant(
    plantId: number,
  ): Promise<Plant | undefined> {
    try {
      const response = await this.plantRepository.findOne({
        select: ['downtimeTicketReclassificationThreshold'],
        where: { plantId },
      });

      return response || undefined;
    } catch (error) {
      if (error instanceof Error) {
        this.logger.error(
          `Failed to get threshold  downtime  for plant ${plantId}: ${error.message}`,
        );
      } else {
        this.logger.error(
          `Failed to get threshold  downtime  for plant ${plantId}: ${String(error)}`,
        );
      }
      return undefined;
    }
  }
}

