@Injectable()
export class ProductionLineService {
  private readonly logger = new AppLogger();

  public constructor(
    @InjectRepository(ProductionLine)
    private readonly productionLineRepo: Repository<ProductionLine>,
  ) {}

  public async getProdLineIdsByUap(
    uapId: string,
  ): Promise<Array<ProductionLine>> {
    try {
      const productionLines = await this.productionLineRepo.find({
        where: { uapId },
      });

      return productionLines;
    } catch (error) {
      this.logger.error('Error getting production line IDs by UAP', error);
      throw error;
    }
  }

  public async getProdlines(
    plant: number,
    uap?: string,
  ): Promise<Array<ProductionLineDto>> {
    try {
      let query = this.productionLineRepo
        .createQueryBuilder('prodLine')
        .select(['prodLine.prodLineId', 'prodLine.prodLineDesc'])
        .where('prodLine.plant = :plant', { plant });

      if (uap) {
        query = query.andWhere('prodLine.uapId = :uap', { uap }); // Filter by uapId if provided
      }

      const productionLines = await query.getMany(); // Get the results
      // Map the workcenters data into WorkcenterResDTO format
      const productionLineDtos: Array<ProductionLineDto> = productionLines.map(
        (prodline) => ({
          prodLineDesc: prodline.prodLineDesc || '', // Ensure workcenterDesc is included in the result
          prodLineId: prodline.prodLineId, // Assuming workcenterId exists in your workcenter entity
        }),
      );
      // Return only the prodLineId in an array
      return productionLineDtos;
    } catch (error) {
      this.logger.error(error);
      throw new Error(`Failed to retrieve production lines: ${error.message}`);
    }
  }
}

