import { Entity, PrimaryColumn, Column, OneToMany } from 'typeorm';
import { TimeStamp } from '@/modules/generics/timestamp';
import { ResourceType } from '@/modules/resource-type/resource-type.entity';

@Entity('resource')
export class Resource extends TimeStamp {
  @PrimaryColumn({ length: 20, name: 'resource_id', nullable: false })
  public resourceId: string;

  @PrimaryColumn({ name: 'plant', nullable: false })
  public plant: number;

  @Column({ length: 8, name: 'workcenter_id', nullable: true })
  public workcenterId: string;

  @Column({ length: 35, name: 'resource_name', nullable: true })
  public resourceName: string;

  @Column({ length: 4, name: 'managed_by', nullable: true })
  public managedBy: string;

  @Column({ name: 'seq_nb_activate', nullable: true })
  public seqNbActivate: boolean;

  @Column({ length: 1, name: 'display_type', nullable: true })
  public displayType: string;

  @Column({ length: 30, name: 'type', nullable: true })
  public type: string;

  @OneToMany(() => ResourceType, (resourceType) => resourceType.resource)
  public resourceTypes: Array<ResourceType>;

  @Column({ name: 'gap_id', nullable: true })
  public gapId: string;

  @Column({ name: 'gap_desc', nullable: true })
  public gapDesc: string;
}

