import { ProductionLine } from '../production-line/production-line.entity';
import { Workcenter } from '../workcenter/workcenter.entity';
import { AssignGapToResourcesResponseDto } from './dtos/assign-gap-to-resources-response.dto';
import { AssignGapToResourcesDto } from './dtos/assign-gap-to-resources.dto';
import { ResourceWithMesInfoResponseDto } from './dtos/get-resource-with-mes-info-response.dto';
import { ResourceDto } from './dtos/get-resource.dto';
import { GetResourcesByGapIdResponseDto } from './dtos/get-resources-by-gapid-response.dto';
import { GetWorkcentersForResourcesResponseDto } from './dtos/get-workcenters-response.dto';
import { UnassignGapFromResourceResponseDto } from './dtos/unassign-gap-from-resource-response.dto';
import { UpdateResourceParameterDto } from './dtos/update-resource.parameter.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { ResourceResponseDTO } from '@/modules/resource/dtos/resource-response.dto';
import { Resource } from '@/modules/resource/resource.entity';

@Injectable()
export class ResourceService {
  private readonly logger = new AppLogger(ResourceService.name);

  public constructor(
    @InjectRepository(Resource)
    private readonly resourceRepo: Repository<Resource>,
  ) {}

  public async getResourceDetailsByWcId(
    workcenterId: string,
    plant: number,
  ): Promise<ResourceResponseDTO> {
    try {
      const resources = await this.resourceRepo
        .createQueryBuilder('resource')
        .innerJoinAndSelect('resource.resourceTypes', 'resourceType')
        .where('resource.workcenter_id= :workcenterId', { workcenterId })
        .andWhere('resource.plant = :plant', { plant })
        .andWhere('resourceType.resourceType = :resourceType', {
          resourceType: 'LAU',
        })
        .getOne();

      if (!resources) {
        throw new NotFoundException('resource not Found');
      }

      return {
        resourceId: resources.resourceId,
        resourceType: resources.resourceTypes,
        seqNbActivated: resources.seqNbActivate,
      };
    } catch (error) {
      this.logger.error(`Failed to retrieve resource: ${error.message}`);
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve resource',
              error,
            );
      throw errorNotFoundException;
    }
  }

  public async getResourceDetailsByWcIds(
    workcenterIds: Array<string>,
    plant: number,
  ): Promise<Record<string, ResourceResponseDTO>> {
    try {
      const resources = await this.resourceRepo
        .createQueryBuilder('resource')
        .innerJoinAndSelect('resource.resourceTypes', 'resourceType')
        .where('resource.workcenter_id IN (:...workcenterIds)', {
          workcenterIds,
        })
        .andWhere('resource.plant = :plant', { plant })
        .andWhere('resourceType.resource_type = :resourceType', {
          resourceType: 'LAU',
        })
        .getMany();

      if (!resources || resources.length === 0) {
        throw new NotFoundException('No resources found');
      }

      // Use a Record to map workcenterId to ResourceResponseDTO
      const resourceMap: Record<string, ResourceResponseDTO> = {};

      for (const resource of resources) {
        resourceMap[resource.workcenterId] = {
          resourceId: resource.resourceId,
          resourceType: resource.resourceTypes,
          seqNbActivated: resource.seqNbActivate,
        };
      }

      return resourceMap;
    } catch (error) {
      this.logger.error(`Failed to retrieve resources: ${error.message}`);
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve resources',
              error,
            );
      throw errorNotFoundException;
    }
  }

  // Method to get resource IDs by plant
  public async getResourceByPlant(plant: number): Promise<Array<ResourceDto>> {
    const resources = await this.resourceRepo.find({
      select: ['resourceId', 'resourceName'],
      where: { plant },
    });
    return resources.map((resource) => ({
      resourceId: resource.resourceId,
      resourceName: resource.resourceName,
    }));
  }

  // Method to get resource IDs by plant
  public async getResourcesByPlant(plant: number): Promise<Array<string>> {
    try {
      const resources = await this.resourceRepo.find({
        select: ['resourceId'],
        where: { plant },
      });
      if (resources.length === 0) {
        throw new NotFoundException(`Resources not found [plant: ${plant}]`);
      }
      return resources.map((resource) => resource.resourceId);
    } catch (error) {
      this.logger.error(
        `Failed to retrieve resources [plant: ${plant}]: ${error.message}`,
      );

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve resources');
      }
      throw error;
    }
  }

  public async getResources(
    plant: number,
    uap?: string,
    productionLine?: string,
    workcenter?: string,
  ): Promise<Array<ResourceDto>> {
    try {
      if (!plant) {
        throw new BadRequestException('Plant is required');
      }

      let query = this.resourceRepo
        .createQueryBuilder('resource')
        .innerJoin(
          Workcenter,
          'workcenter',
          'resource.workcenter_id = workcenter.workcenter_id',
        )
        .where('resource.plant = :plant', { plant });

      // Filtrer par Workcenter si fourni
      if (workcenter) {
        query = query.andWhere('resource.workcenter_id = :workcenter', {
          workcenter,
        });
      }

      // Si prodLine est fourni, on filtre via Workcenter
      if (productionLine) {
        query = query.andWhere('workcenter.prod_line_id = :productionLine', {
          productionLine,
        });
      }

      // Si uap est fourni, on doit ajouter la jointure avec ProductionLine
      if (uap) {
        query = query
          .innerJoin(
            ProductionLine,
            'prodLine',
            'workcenter.prod_line_id = prodLine.prod_line_id',
          )
          .andWhere('prodLine.uap_id = :uap', { uap });
      }

      const resources = await query.getMany();

      // Mapping des résultats
      const resourceDto: Array<ResourceDto> = resources.map((resource) => ({
        resourceId: resource.resourceId,
        resourceName: resource.resourceName || '',
      }));

      return resourceDto;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve resources: ${error.message}`,
        error,
      );
      throw new Error(`Failed to retrieve resources: ${error.message}`);
    }
  }

  public async fetchResourcesWithMESInfo(
    plant: number,
    resourceId: string,
  ): Promise<ResourceWithMesInfoResponseDto | undefined> {
    try {
      const resource = (await this.resourceRepo
        .createQueryBuilder('resource')
        .leftJoin(
          'workcenter',
          'workcenter',
          'resource.workcenter_id = workcenter.workcenter_id',
        )
        .select([
          'resource.plant AS "plant"',
          'resource.resource_id AS "resourceId"',
          'resource.resource_name AS "resourceName"',
          'resource.workcenter_id AS "workcenterId"',
          'resource.seq_nb_activate AS "seqNbActivated"',
