  public async assignGapToResources(
    assignGapDto: AssignGapToResourcesDto,
  ): Promise<AssignGapToResourcesResponseDto> {
    try {
      const { resourceIds, gapId, plant, gapDesc } = assignGapDto;
      // Update resources with the gapId
      const updateResult = await this.resourceRepo
        .createQueryBuilder()
        .update(Resource)
        .set({ gapId, gapDesc })
        .where('plant = :plant', { plant })
        .andWhere('resource_id IN (:...resourceIds)', { resourceIds })
        .execute();

      if (!updateResult.affected || updateResult.affected === 0) {
        return {
          updatedCount: 0,
          updatedResourceIds: resourceIds,
          gapId,
          gapDesc,
        } as AssignGapToResourcesResponseDto;
      }

      return {
        updatedCount: updateResult.affected,
        updatedResourceIds: resourceIds,
        gapId,
        gapDesc,
      } as AssignGapToResourcesResponseDto;
    } catch (error) {
      this.logger.error(
        `Failed to assign gapId to resources: ${error.message} | Plant: ${assignGapDto.plant}, GapId: ${assignGapDto.gapId}, ResourceIds: ${JSON.stringify(assignGapDto.resourceIds)}`,
      );
      return {
        updatedCount: 0,
        updatedResourceIds: assignGapDto.resourceIds,
        gapId: assignGapDto.gapId,
        gapDesc: assignGapDto.gapDesc,
      } as AssignGapToResourcesResponseDto;
    }
  }

  public async unassignGapFromResource(
    plant: number,
    resourceId: string,
    gapId: string,
  ): Promise<UnassignGapFromResourceResponseDto> {
    try {
      // First verify the resource exists with the specified gapId
      const resource = await this.resourceRepo.findOne({
        where: {
          plant,
          resourceId,
          gapId,
        },
      });

      if (!resource) {
        return {
          success: false,
          resourceId,
          message: `Resource ${resourceId} not found`,
        };
      }

      // Update the resource to set gapId and gapDesc to null
      const updateResult = await this.resourceRepo
        .createQueryBuilder()
        .update(Resource)
        .set({
          gapId: null as unknown as string,
          gapDesc: null as unknown as string,
        })
        .where('plant = :plant', { plant })
        .andWhere('resource_id = :resourceId', { resourceId })
        .andWhere('gap_id = :gapId', { gapId })
        .execute();

      if (!updateResult.affected || updateResult.affected === 0) {
        return {
          success: true,
          resourceId,
          message: `Failed to unassign gapId from resource ${resourceId}`,
        };
      }
      return {
        success: true,
        resourceId,
        message: 'GapId successfully removed from resource',
      };
    } catch (error) {
      return {
        success: false,
        resourceId,
        message: `Failed to unassign gapId from resource Plant: ${plant}, ResourceId: ${resourceId}, GapId: ${gapId} | ${error.message}`,
      };
    }
  }

  public async getWorkcentersForResources(
    plant: number,
    resourceIds: Array<string>,
  ): Promise<GetWorkcentersForResourcesResponseDto> {
    try {
      // Query resources with their workcenter IDs
      const resources = await this.resourceRepo
        .createQueryBuilder('resource')
        .select([
          'resource.resource_id AS "resourceId"',
          'resource.workcenter_id AS "workcenterId"',
        ])
        .where('resource.plant = :plant', { plant })
        .andWhere('resource.resource_id IN (:...resourceIds)', { resourceIds })
        .getRawMany();
      if (resources.length === 0) {
        return { resources: [], totalCount: 0 };
      }
      // Create a map of found resources
      const resourceMap = new Map(
        resources.map((r) => [r.resourceId, r.workcenterId]),
      );

      // Build response including resources that weren't found (null workcenter)
      const result = resourceIds.map((resourceId) => ({
        resourceId,
        workcenterId: resourceMap.get(resourceId) || null,
      }));

      return {
        resources: result,
        totalCount: resourceIds.length,
      };
    } catch (error) {
      this.logger.error(
        `Failed to get workcenters for resources: ${error.message} | Plant: ${plant}, ResourceIds: ${JSON.stringify(resourceIds)}`,
      );
      return { resources: [], totalCount: 0 };
    }
  }

  public async checkResourceTypeJIT(
    plant: number,
    resourceId: string,
  ): Promise<boolean> {
    try {
      const resource = await this.resourceRepo.findOne({
        where: {
          plant,
          resourceId,
          type: 'JIT',
        },
      });

      if (!resource) {
        return false;
      }

      return true;
    } catch (error) {
      if (error instanceof Error) {
        this.logger.error(
          `Failed to check resource type for resource ${resourceId}: ${error.message}`,
        );
      } else {
        this.logger.error(
          `Failed to check resource type for resource ${resourceId}: ${String(error)}`,
        );
      }
      return false;
    }
  }
}

