import { Entity, PrimaryColumn, Column } from 'typeorm';
import { TimeStamp } from '@/modules/generics/timestamp';

@Entity('workcenter')
export class Workcenter extends TimeStamp {
  @PrimaryColumn({ length: 8, name: 'workcenter_id', nullable: false })
  public workcenterId: string;

  @PrimaryColumn({ name: 'plant', nullable: false })
  public plant: number;

  @Column({ length: 1024, name: 'advance_picking_duration', nullable: true })
  public advancePickingDuration: string;

  @Column({ length: 255, name: 'workcenter_desc', nullable: true })
  public workcenterDesc: string;

  @Column({ length: 25, name: 'prod_line_id', nullable: true })
  public prodLineId: string;

  @Column({ default: false, name: 'ewm_flow', nullable: false })
  public ewmFlow: boolean;

  @Column({
    default: 'MANUAL',
    length: 10,
    name: 'alert_creation',
    nullable: false,
  })
  public alertCreation: string;

  @Column({ default: false, name: 'is_mes', nullable: false })
  public isMes: boolean;

  @Column({ name: 'min_launcher_waiting_time', nullable: true })
  public minLauncherWaitingTime: number;

  @Column({ name: 'max_launcher_waiting_time', nullable: true })
  public maxLauncherWaitingTime: number;
}

