  public async getWorkcenterDetailsById(
    plant: number,
    workcenterId: string,
  ): Promise<WorkcenterResponseDTO> {
    try {
      const workcenterDetail = (await this.workcenterRepo
        .createQueryBuilder('workcenter')
        .leftJoinAndMapOne(
          'workcenter.prodLine',
          ProductionLine,
          'prodLine',
          'workcenter.prodLineId = prodLine.prodLineId AND workcenter.plant = prodLine.plant',
        )
        .select([
          'workcenter.advancePickingDuration',
          'workcenter.workcenterDesc',
          'workcenter.maxLauncherWaitingTime',
          'workcenter.minLauncherWaitingTime',
          'workcenter.alertCreation',
          'prodLine.uapId',
        ])
        .where('workcenter.plant = :plant', { plant })
        .andWhere('workcenter.workcenterId = :workcenterId', { workcenterId })
        .getOne()) as WorkcenterProdlineDTO; // Cast the result to the custom type

      if (!workcenterDetail) {
        throw new NotFoundException(
          `Workcenter not found [plant: ${plant}, workcenterId: ${workcenterId}]`,
        );
      }
      return {
        advancePickingDuration: workcenterDetail.advancePickingDuration,
        alertCreation: workcenterDetail.alertCreation,
        description: workcenterDetail.workcenterDesc,
        maxLauncherWaitingTime: workcenterDetail.maxLauncherWaitingTime,
        minLauncherWaitingTime: workcenterDetail.minLauncherWaitingTime,
        uapId: workcenterDetail.prodLine?.uapId, // Access the dynamically mapped property
      };
    } catch (error) {
      this.logger.error(
        `Failed to retrieve workcenter [plant: ${plant}, workcenterId: ${workcenterId}]: ${error.message}`,
      );

      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve workcenter');
      }
      throw error;
    }
  }

