  public async getWokcenterEwmFlow(
    plantIds: Array<number>,
  ): Promise<Record<number, Array<string>>> {
    try {
      const placeholders = plantIds.join(', ');

      const query = `SELECT w.plant AS plant,
       (
           SELECT wc.workcenter_id as workcenter
           FROM workcenter wc
           WHERE wc.plant = w.plant
             AND wc.ewm_flow = 1
			         FOR JSON PATH

       ) AS workcenters
FROM workcenter w
WHERE w.ewm_flow = 1
  AND w.plant IN (${placeholders})
GROUP BY w.plant;
`;
      const workcenters = await this.workcenterRepo.query(query);

      if (workcenters.length === 0) {
        throw new NotFoundException(
          `Workcenter  with EWM Flow not found [plant: ${plantIds}]`,
        );
      }
      // Grouping by plant

      const result = Object.assign(
        {},
        ...workcenters.map((row: { plant: number; workcenters: string }) => ({
          [row.plant]: (
            JSON.parse(row.workcenters) as Array<{ workcenter: string }>
          ).map((item) => item.workcenter),
        })),
      );
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve EWM Flow information of workcenters for  [plant: ${plantIds}  ]: ${error.message}`,
      );

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Workcenter  with EWM Flow not found [plant: ${plantIds}]`,
        );
      }
      throw error;
    }
  }

  public async updateWorkcentersBulk(
    plant: number,
    updateDtos: Array<UpdateWorkcenter>,
  ): Promise<Array<Workcenter>> {
    // Extract workcenterIds from the DTOs
    const workcenterIds = updateDtos.map((dto) => dto.workcenterId);

    // Find all workcenters that match the given plant and workcenterIds
    const workcenters = await this.workcenterRepo.find({
      where: { plant, workcenterId: In(workcenterIds) },
    });

    if (workcenters.length !== updateDtos.length) {
      const missingIds = workcenterIds.filter(
        (id) => !workcenters.some((wc) => wc.workcenterId === id),
      );
      throw new Error(
        `Some workcenters were not found for plant ${plant}: Missing IDs: ${missingIds.join(', ')}`,
      );
    }
    try {
      // Update workcenters with provided fields
      const updatedWorkcenters = workcenters.map((workcenter) => {
        const foundDto = updateDtos.find(
          (dto: UpdateWorkcenter) =>
            dto.workcenterId === workcenter.workcenterId,
        );
        if (foundDto) {
          Object.assign(workcenter, foundDto);
        }
        return workcenter;
      });
      const chunkArray = (
        array: Array<Workcenter>,
        size: number,
      ): Array<Array<Workcenter>> => {
        const result: Array<Array<Workcenter>> = [];
        for (let index = 0; index < array.length; index += size) {
          result.push(array.slice(index, index + size));
        }
        return result;
      };
      const workcenterChunks = chunkArray(updatedWorkcenters, 100);
      const savePromises = workcenterChunks.map((chunk) =>
        this.workcenterRepo.save(chunk),
      );
      await Promise.all(savePromises);
      if (updatedWorkcenters.length > 0) {
        this.publishEwmWorkcenterMessage(`Workcenters updated`);
      }
      return updatedWorkcenters;
    } catch (error) {
      this.logger.error(
        `Failed to update  workcenters for  [plant: ${plant}  ]: ${error.message}`,
      );
      throw new InternalServerErrorException(
        `Failed to update  workcenters for [plant: ${plant}] , ${workcenterIds} `,
      );
    }
  }

  public async getWorkcenterIdsByProdline(
    productionLineId: string,
  ): Promise<Array<Workcenter>> {
    try {
      const workcenters = await this.workcenterRepo.find({
        where: { prodLineId: productionLineId },
      });

      if (workcenters.length === 0) {
        throw new NotFoundException(
          `No workcenters found for prodLineId: ${productionLineId}`,
        );
      }

      return workcenters;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve workcenters for prodLineId ${productionLineId}: ${error.message}`,
      );
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          `Failed to retrieve workcenters for prodLineId ${productionLineId}`,
        );
      }
      throw error;
    }
  }

  public async getWorkcenters(
    plant: number,
    uap?: string,
    productionLine?: string,
  ): Promise<Array<WorkcenterResultDTO>> {
    try {
      let query = this.workcenterRepo
        .createQueryBuilder('workcenter')
        .where('workcenter.plant = :plant', { plant });

      if (productionLine) {
        query = query.andWhere('workcenter.prodLineId = :prodLine', {
          prodLine: productionLine,
        });
      } else if (uap) {
        query = query
          .innerJoin(
            ProductionLine,
            'prodLine',
            'workcenter.prodLineId = prodLine.prodLineId',
          )
          .andWhere('prodLine.uapId = :uap', { uap });
      }

      const workcenters = await query.getMany(); // Get the workcenterId results
      // Map the workcenters data into WorkcenterResDTO format
      const workcenterDtos: Array<WorkcenterResultDTO> = workcenters.map(
        (workcenter) => ({
          workcenterDesc: workcenter.workcenterDesc || '', // Assuming workcenterDesc exists as description
          workcenterId: workcenter.workcenterId, // Assuming workcenterId exists in your workcenter entity
        }),
      );

      return workcenterDtos;
    } catch (error) {
      this.logger.error(error);
      throw new Error(`Failed to retrieve workcenter: ${error.message}`); // Throw an error instead of using res
    }
  }

  public async getWorkcentersDetailsByListId(
    plant: number,
    workcenterIds: Array<string>,
  ): Promise<Record<string, WorkcenterListResponseDTO>> {
    try {
      // Use findBy with In operator to fetch workcenters
      const workcenterDetails = await this.workcenterRepo.find({
        select: ['advancePickingDuration', 'workcenterDesc', 'workcenterId'],
        where: {
          plant,
          workcenterId: In(workcenterIds),
        },
      });
      const result: Record<string, WorkcenterListResponseDTO> = {};
      for (const item of workcenterDetails) {
        const { workcenterId, workcenterDesc, advancePickingDuration } = item;
        result[workcenterId] = {
          advancePickingDuration,
          description: workcenterDesc || '',
        };
      }
      return result;
    } catch (error) {
      this.logger.error(`Failed to retrieve workcenters: ${error.message}`);
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve workcenters',
              error,
            );
      throw errorNotFoundException;
    }
  }

  public async getAdvancePickingDurationsByWorkcentersAndPlant(
    plant: number,
    workcenterIds: Array<string>,
  ): Promise<Array<{ workcenterId: string; advancePickingDuration: string }>> {
    try {
      // Find the workcenters for the given plant and filter by the provided workcenter IDs
      const workcenters = await this.workcenterRepo.find({
        where: { plant, workcenterId: In(workcenterIds) }, // In() is a TypeORM operator for array matching
      });
      const durationsMap = new Map<string, string>();

      // Populate the map with workcenterId and its corresponding advancePickingDuration
      for (const wc of workcenters) {
        const duration = wc.advancePickingDuration?.trim() || '0'; // Use '0' as default if null or empty
        durationsMap.set(wc.workcenterId, duration);
      }
      // Return the result in the required format
      return [...durationsMap.entries()].map(
        ([workcenterId, advancePickingDuration]) => ({
          workcenterId,
          advancePickingDuration,
        }),
      );
    } catch (error) {
      this.logger.error(
        `Error while retrieving advance picking durations for workcenters in plant ${plant}: ${error}`,
      );
      throw new InternalServerErrorException(
        `Failed to retrieve advance picking durations for workcenters in plant ${plant}.`,
      );
    }
  }

  public async updateMesWorkcenter(
    workcenterId: string,
    plant: number,
    updateDto: UpdateMesWorkcenter,
  ): Promise<MesWorkcenterDto> {
    try {
      const workcenter = await this.workcenterRepo.findOne({
        where: {
          plant,
          workcenterId,
        },
      });
      if (!workcenter) {
        throw new NotFoundException('Workcenter not found');
      }
      Object.assign(workcenter, updateDto);
      const newWorkcenter = await this.workcenterRepo.save(workcenter);
      return newWorkcenter;
    } catch (error) {
      this.logger.error(
        `Failed to update workcenter [plant: ${plant}, workcenterId: ${workcenterId}]: ${error.message}`,
      );
      throw new InternalServerErrorException(
        `Failed to update workcenter [plant: ${plant}, workcenterId: ${workcenterId}]`,
      );
    }
  }

  public async getWorkcentersByPlant(
    plant: number,
  ): Promise<Array<WorkcenterPlantDto>> {
    try {
      const workcenters = await this.workcenterRepo.find({
        where: { plant },
        select: ['workcenterId', 'isMes'],
      });

      return workcenters.map((wc) => ({
        workcenterId: wc.workcenterId,
        isMes: wc.isMes,
      }));
    } catch {
      throw new InternalServerErrorException(
        'Failed to fetch workcenters. Please try again later.',
      );
    }
  }

  public async getMesWorkcentersByPlant(
    plant: number,
  ): Promise<WorkcenterFlaggedMesDto> {
    try {
      const workcenters = await this.workcenterRepo.find({
        where: { plant, isMes: true },
        select: ['workcenterId'],
      });
      const result: WorkcenterFlaggedMesDto = {
        workcenters: workcenters.map((wc) => wc.workcenterId),
      };

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to fetch MES workcenters for plant ${plant}: ${
          error.message ?? error
        }`,
      );

      return { workcenters: [] };
    }
  }
}

