import 'dotenv/config';
import { createRequire } from 'node:module';
import path from 'node:path';
import { Logger } from '@nestjs/common';
import { DataSource, EntityTarget, ObjectLiteral } from 'typeorm';
import { SqlServerConnectionOptions } from 'typeorm/driver/sqlserver/SqlServerConnectionOptions';
import { mssqlConfiguration } from '@/config/database/mssql/configuration';
import { DefaultMssqlConfigurationService } from '@/config/database/mssql/default.mssql.config.service';
import { PhysicalAssetClassDescription } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-description/physical-asset-class-description.entity';
import { PhysicalAssetClassProperty } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property/physical-asset-class-property.entity';
import { PhysicalAssetClassPropertyDescription } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class-property-description/physical-asset-class-property-description.entity';
import { PhysicalAssetClass } from '@/modules/isa9-physical-asset-model/physical-asset-class/physical-asset-class.entity';
import { PropertyDataType } from '@/modules/isa95-common/property-data-type/property-data-type.entity';
import { EquipmentLevel } from '@/modules/isa95-equipment-model/equipment/equipment-level/equipment-level.entity';
import { EquipmentPropertyDescription } from '@/modules/isa95-equipment-model/equipment/equipment-property-description/equipment-property-description.entity';
import { EquipmentClassDescription } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-description/equipment-class-description.entity';
import { EquipmentClassProperty } from '@/modules/isa95-equipment-model/equipment-class/equipment-class-property/equipment-class-property.entity';
import { EquipmentClass } from '@/modules/isa95-equipment-model/equipment-class/equipment-class.entity';
import { getDatabaseConnectionProperties } from '@/providers/database/mssql/mssql.connection.factory';
import {
  discoverSeedDataFiles,
  runSeedDataFiles,
} from '@/seeding/core/seed-runner';

const logger = new Logger('SeedRunner');
const nodeRequire = createRequire(`${process.cwd()}/package.json`);
const pathModule =
  path ?? (nodeRequire('node:path') as typeof import('node:path'));
const seedDataDirectoryPath = 'src/seeding/data';

/**
 * Registry of JSON seed table keys to their TypeORM entity classes.
 * Add entries here when introducing new seed data files for this repo.
 */
const entityRegistry = new Map<string, EntityTarget<ObjectLiteral>>([
  ['equipment-level', EquipmentLevel],
  ['equipment-class', EquipmentClass],
  ['equipment-class-description', EquipmentClassDescription],
  ['equipment-class-property', EquipmentClassProperty],
  ['equipment-property-description', EquipmentPropertyDescription],
  ['physical-asset-class', PhysicalAssetClass],
  ['physical-asset-class-description', PhysicalAssetClassDescription],
  ['physical-asset-class-property', PhysicalAssetClassProperty],
  [
    'physical-asset-class-property-description',
    PhysicalAssetClassPropertyDescription,
  ],
  ['property-data-type', PropertyDataType],
]);

/**
 * Build a standalone DataSource scoped to the seeding CLI.
 * Constructed from the same environment-driven config as migration.data.source.ts
 * but kept isolated so it does not interfere with NestJS TypeORM lifecycle.
 *
 * CRITICAL: Always sets synchronize: false for seeding. Schema is already correct
 * from migrations; seeding only inserts data. If synchronize: true were used,
 * TypeORM would attempt to drop and recreate constraints, causing failures.
 * @returns Uninitialized TypeORM DataSource.
 */
function buildSeedDataSource(): DataSource {
  const mssqlConfig = mssqlConfiguration().mssql;
  const connectionProperties = getDatabaseConnectionProperties(
    new DefaultMssqlConfigurationService(mssqlConfig),
  );
  return new DataSource({
    ...connectionProperties,
    logging: false,
    synchronize: false, // Always false for seeding CLI — schema is ready from migrations
  } as SqlServerConnectionOptions);
}

/**
 * Parse CLI selectors used to filter seed data files.
 * @param cliArguments Raw CLI arguments.
 * @returns A normalized selectors list.
 */
function parseSelectors(cliArguments: Array<string>): Array<string> {
  if (cliArguments.length === 0) {
    return ['all'];
  }
  return cliArguments;
}

/**
 * Resolve absolute seed data directory path.
 * @param currentWorkingDirectory Current process working directory.
 * @returns Absolute path for seed data directory.
 */
function resolveSeedDataDirectoryPath(currentWorkingDirectory: string): string {
  return pathModule.resolve(currentWorkingDirectory, seedDataDirectoryPath);
}

/**
 * Guard: verify all migrations have been applied before seeding.
 * Exits with code 1 when pending migrations are detected to prevent
 * seeding against a schema that FK-references tables not yet created.
 * @param dataSource Initialized TypeORM DataSource.
 */
async function assertNoPendingMigrations(
  dataSource: DataSource,
): Promise<void> {
  const hasPending = await dataSource.showMigrations();
  if (hasPending) {
    logger.error(
      'Pending migrations detected. Apply all migrations before running seeds.',
    );
    process.exitCode = 1;
    throw new Error('Aborting seed: unapplied migrations exist.');
  }
  logger.log('Migration check passed — no pending migrations.');
}

/**
 * Execute seeding flow for the selected filters.
 * @param selectors Selector list.
 * @returns Promise resolved when seeding completes.
 */
async function executeSeeding(selectors: Array<string>): Promise<void> {
  const dataSource = buildSeedDataSource();
  await dataSource.initialize();

  try {
    await assertNoPendingMigrations(dataSource);
    const dataDirectoryPath = resolveSeedDataDirectoryPath(process.cwd());
    const seedDataFiles = await discoverSeedDataFiles(
      dataDirectoryPath,
      entityRegistry,
    );
    await runSeedDataFiles({
      dataSource,
      logger,
      seedDataFiles,
      selectors,
    });
  } finally {
    if (dataSource.isInitialized) {
      await dataSource.destroy();
    }
  }
}

/**
 * Handle seeding failures.
 * @param error Caught error.
 */
function handleSeedFailure(error: unknown): void {
  logger.error(
    'Error while running seed plans.',
    error instanceof Error ? error.stack : String(error),
  );
  process.exitCode = 1;
}

/**
 * Execute seeding from CLI arguments.
 */
function runSeedCli(): void {
  const selectors = parseSelectors(process.argv.slice(2));
  logger.log(`Selected seed filters: ${selectors.join(', ')}`);
  executeSeeding(selectors)
    .then(() => {
      logger.log('Seeding completed successfully.');
    })
    .catch((error) => {
      handleSeedFailure(error);
    });
}

runSeedCli();

